(function () {
  "use strict";
  var translations = {
  "bn": {
    "cli_ref_discovery": "কমান্ড খোঁজা, সমস্যা যাচাই ও স্থানীয় প্রমাণ",
    "cli_ref_conventions": "নিচের প্রতিটি কমান্ডের আগে <code>killerbench-cli</code> লিখুন। স্পেসযুক্ত পথ বা লেখা উদ্ধৃতিচিহ্নে রাখুন। বর্গাকার বন্ধনী ঐচ্ছিক আর্গুমেন্ট বোঝায়; উল্লম্ব দাগ বিকল্পগুলো আলাদা করে। <code>...</code> থাকলে পুরো অপশনটি পুনরাবৃত্তি করুন। অপশন কেবল সংশ্লিষ্ট কমান্ডের জন্য প্রযোজ্য। মেশিনে পাঠযোগ্য নামের তালিকার জন্য <code>capabilities</code> ব্যবহার করুন। এতে ভবিষ্যৎ রিলিজের জন্য সংরক্ষিত নামও থাকে। কনসোলে নির্দেশনা পেতে <code>help</code>, <code>--help</code>, <code>-h</code> ব্যবহার করুন বা কোনো আর্গুমেন্ট দেবেন না।",
    "cli_ref_exceptions": "সাধারণ পূর্বরূপ নিয়মের কিছু ব্যতিক্রম আছে: <code>symptom run --repair</code>, <code>workflow --auto-repair</code> এবং <code>debloat-review</code>-এর তিনটি পাওয়ার অপশন <code>--execute</code> ছাড়াই তাদের নথিভুক্ত পরিবর্তনের অনুমতি দেয়। <code>validate-native</code> কেবল সুরক্ষিত, পরীক্ষার পর ফেলে দেওয়ার উপযোগী পরিবেশে ইচ্ছাকৃত ত্রুটি তৈরি করে। প্যাক রপ্তানি, সংরক্ষিত পরিকল্পনা, জার্নাল ও প্রতিবেদনও স্থানীয় ফাইল লেখে। নথিতে উল্লেখ থাকলেই JSON পাওয়া যায়; প্যাক খোঁজা ও যাচাই, সাধারণ টেক্সট বিশ্লেষণ এবং কিছু পূর্বরূপ টেক্সট ব্যবহার করে। কমান্ড সফল হলেও অগ্রগতি ও সক্ষমতার বার্তা standard error-এ দেখা যেতে পারে।",
    "cli_ref_profile_backup_limits": "<code>profiles --backup-to</code> এনক্রিপশনবিহীন প্রোফাইল এন্ট্রি সমর্থন করে। ব্যাকআপের গন্তব্য তৈরির আগেই EFS-এনক্রিপ্ট করা উৎস প্রত্যাখ্যান করা হয়।",
    "cli_ref_capabilities": "<code>capabilities [--json]</code>: উভয় রূপেই JSON ফেরত দেয়: <code>schemaVersion</code> (1), অ্যাসেম্বলির <code>version</code> এবং সাজানো, পুনরাবৃত্তিহীন <code>commands</code> (স্ট্রিং)। কোনো রোগনির্ণয় বা মেরামত করে না। কেবল ঐচ্ছিক <code>--json</code> গ্রহণ করে; সফল হলে প্রস্থান কোড 0, অন্য আর্গুমেন্টে 2। তালিকায় নাম থাকা নেটিভ সমর্থন বা বর্তমান রিলিজে প্রাপ্যতার প্রমাণ নয়।",
    "cli_ref_pack": "<code>pack list | pack export PACK_ID OUTPUT.json | pack validate PACK.json</code>: অন্তর্ভুক্ত প্যাক, রেসিপির সক্ষমতার লেবেল ও প্রিমিটিভের তালিকা দেখায়; আগে থেকে নেই এমন আউটপুট পথে একটি অন্তর্ভুক্ত প্যাক রপ্তানি করে; অথবা Windows প্রিমিটিভ লাইব্রেরি অনুযায়ী স্থানীয় প্যাক যাচাই করে। আউটপুট টেক্সট; কোনো রেসিপি চলে না। রপ্তানি প্রয়োজনীয় মূল ডিরেক্টরি তৈরি করে। প্রস্থান কোড: সাফল্যে 0; ভুল আর্গুমেন্ট, অজানা ID বা বিদ্যমান আউটপুটে 2; অবৈধ বা পড়া যায় না এমন প্যাকে 3।",
    "cli_ref_symptom": "<code>symptom list | symptom search TEXT | symptom run SYMPTOM_ID [--repair] [--explicit] [--option NAME=VALUE]... [--answer NODE=KEY]... [--json]</code>: সমর্থিত লক্ষণের ID দেখায় বা খোঁজে, তারপর একটি সীমিত সমস্যা যাচাইয়ের বৃক্ষ চালায়। ডিফল্টভাবে শুধু শনাক্ত করে। <code>--repair</code> নতুন যাচাইসহ স্বয়ংক্রিয় প্যাক রেসিপির অনুমতি দেয়; <code>--explicit</code> অতিরিক্তভাবে স্পষ্ট অপশন প্রয়োজন এমন রেসিপি নিশ্চিত করে এবং এর জন্য <code>--repair</code> প্রয়োজন। প্রতিটি রেসিপি সর্বোচ্চ একবার প্রয়োগ হয়; ডিফল্ট সীমা 40 ধাপ, 10 মেরামত ও 30 মিনিট। উত্তরহীন প্রশ্ন খোলা থাকে। স্থানীয় Triage জার্নাল লেখে এবং টেক্সট বা JSON ফেরত দেয়। প্রস্থান কোড: 0 সমাধান হয়েছে বা সম্ভাবনা বাদ গেছে, 3 অমীমাংসিত বা বাধাপ্রাপ্ত, 4 পুনরায় চালু করা প্রয়োজন, 5 কম্পোনেন্ট মেরামত যাচাই হয়েছে কিন্তু লক্ষণ দূর হওয়া নিশ্চিত নয়, 130 বাতিল। অনুসন্ধানে মিল না পেলে 3; ভুল ইনপুটে 2।",
    "cli_ref_investigate": "<code>investigate FILE_PATH [--json]</code>: ব্যাখ্যা, তথ্যসূত্র ও পরবর্তী পদক্ষেপসহ স্থানীয় টেক্সট লগ, সংরক্ষিত EVTX আর্কাইভ বা রপ্তানি করা Windows Events XML নথিতে সমর্থিত প্রমাণের নিয়ম প্রয়োগ করে। টেক্সট আমদানিতে সর্বোচ্চ 1,000,000 অক্ষর ও 10,000 পার্স করা এন্ট্রি পড়ে। EVTX-এর জন্য Windows প্রয়োজন এবং সর্বশেষ 200 রেকর্ড রাখা হয়; XML-এ ফাইলের ক্রমে প্রথম 200 রেকর্ড রাখা হয়। কোনো ইভেন্ট আমদানিতেই তারিখের ফিল্টার নেই। পুরোনো প্রমাণ বর্তমান কম্পিউটারের সুস্থতা নিশ্চিত করে না। বিশ্লেষণের বাতিলকরণ সময়সীমা 15 সেকেন্ড। ডিফল্ট আউটপুট টেক্সট; <code>--json</code> দিলে JSON। প্রস্থান কোড: 0 বিশ্লেষণ সম্পূর্ণ, 3 আংশিক প্রমাণ, 1 অপাঠ্য বা অসমর্থিত ইনপুট, 2 ভুল আর্গুমেন্ট, 130 বাতিল বা সময় শেষ। কোনো মেরামত করে না।",
    "cli_ref_analyze": "<code>analyze TEXT_LOG_PATH [--json]</code>: কারণ নির্ণয় বা পরিবর্তন না করে একটি টেক্সট লগ থেকে স্বতন্ত্র কোডের পর্যবেক্ষণ বের করে। সর্বোচ্চ 1,000,000 অক্ষর পড়ে, 256 কোড ও প্রতি কোডে আটটি তথ্যসূত্র রাখে; বাতিলকরণ সময়সীমা 15 সেকেন্ড। ডিফল্ট টেক্সট, <code>--json</code> দিলে JSON। প্রস্থান কোড: 0 সম্পূর্ণ বিশ্লেষণ, 3 সীমার কারণে কাটা হয়েছে, 1 ইনপুট ব্যর্থতা, 2 ভুল আর্গুমেন্ট, 130 বাতিল বা সময় শেষ।",
    "cli_ref_duplicate_files": "<code>duplicate-files FOLDER [--min-bytes N] [--max-files N] [--report]</code>: একটি স্থানীয় ফোল্ডারে SHA-256 দিয়ে সদৃশ ফাইলের শুধু-পঠন পর্যালোচনা। ডিফল্ট সর্বনিম্ন এক বাইট ও 10,000 ফাইল; সর্বনিম্ন শূন্য হতে পারে, ফাইলের সীমা 1 থেকে 100,000। মোট হ্যাশিংয়ের সীমা 100 GiB। ডিফল্ট JSON, <code>--report</code> দিলে টেক্সট; উভয়টিতেই ফাইলের পথ প্রকাশ পেতে পারে। মুছে ফেলার জন্য কোনো ফাইল বাছাই হয় না। প্রস্থান কোড: 0 সম্পূর্ণ, 3 অসম্পূর্ণ, 1 স্ক্যান/ইনপুট ব্যর্থতা, 2 ত্রুটিপূর্ণ অপশন, 130 বাতিল।",
    "cli_ref_large_files": "<code>large-files FOLDER [--min-bytes N] [--max-files N] [--limit N] [--report]</code>: একটি স্থানীয় ফোল্ডারের ফাইলের আকারের শুধু-পঠন পর্যালোচনা। ডিফল্ট সর্বনিম্ন 100 MiB, 10,000 পরীক্ষিত ফাইল ও 500 সংরক্ষিত ফলাফল। সর্বনিম্ন ধনাত্মক হতে হবে; ফাইলের সীমা 1 থেকে 100,000 এবং ফলাফলের সীমা 1 থেকে 10,000। ডিফল্ট JSON, <code>--report</code> দিলে টেক্সট; আউটপুটে ফাইলের পথ থাকে। প্রস্থান কোড: 0 সম্পূর্ণ, 3 অসম্পূর্ণ, 1 স্ক্যান/ইনপুট ব্যর্থতা, 2 ত্রুটিপূর্ণ অপশন, 130 বাতিল। কোনো পরিষ্কারকরণ করে না।",
    "cli_ref_file_limits": "উভয় ফোল্ডার পর্যালোচনা reparse point এড়িয়ে সীমিতভাবে ফোল্ডার ঘুরে দেখে। ডিফল্ট সীমা: 10,000 ডিরেক্টরি, অপেক্ষমাণ 1,024 ডিরেক্টরি, গভীরতা 128 ও 30 সেকেন্ড। কোনো বিষয়বস্তু পড়া না গেলে বা ফোল্ডার ঘোরা, হ্যাশিং, ফাইল কিংবা ফলাফলের কোনো সীমায় পৌঁছালে ফল অসম্পূর্ণ থাকে। এগুলো কভারেজের সীমা; বাদ পড়া ফাইল নিরাপদ হওয়ার প্রমাণ নয়।",
    "cli_ref_debloat_recover": "<code>debloat-recover power-plan|power-timers|hibernation --folder PATH [--json]</code>: জার্নাল ফোল্ডারের পূর্ণ পথ দিয়ে এক ধরনের অপেক্ষমাণ পাওয়ার অপারেশনের অবস্থা মিলিয়ে যাচাই করে। অপেক্ষমাণ রেকর্ড থাকা একই ফোল্ডার বাছুন, সাধারণত <code>%LOCALAPPDATA%\\KillerBench\\Debloat</code>। <code>--json</code> থাকুক বা না থাকুক, সবসময় JSON ফেরত দেয়; অগ্রগতি standard error-এ যায়। পাওয়ারের পরিবর্তন আবার করে না। নিষ্পত্তি হওয়া স্থানীয় রেকর্ড আর্কাইভ করা হতে পারে। প্রস্থান কোড: 0 অপেক্ষমাণ রেকর্ড নেই বা অবস্থা যাচাই হয়েছে, 3 অমীমাংসিত প্রমাণ, 1 ফাইল/প্রোভাইডার ত্রুটি, 2 ভুল আর্গুমেন্ট বা আপেক্ষিক/অনুপস্থিত ফোল্ডারের পথ, 130 বাতিল। <code>--execute</code> অপশন নেই।",
    "cli_ref_gated": "রিলিজের সীমা ও অস্থায়ী পরীক্ষার পরিবেশে নেটিভ যাচাই",
    "cli_ref_third_party_updates": "<code>third-party-updates</code>: Microsoft.WinGet.Client দিয়ে অ্যাপ আপডেট খোঁজার সংরক্ষিত শুধু-পঠন কমান্ড। বর্তমান রিলিজে বন্ধ; কোনো অনুসন্ধান না করে KillerBench 1.1-এ প্রাপ্যতার বার্তা ও প্রস্থান কোড 2 দেয়। সক্রিয় হলে JSON দেয়; সম্পূর্ণ ও উপলব্ধ অনুসন্ধানে 0, অসম্পূর্ণ বা অনুপলব্ধ অনুসন্ধানে 3, প্রোভাইডার ব্যর্থতায় 1, বাতিলে 130।",
    "cli_ref_third_party_update": "<code>third-party-update ID SOURCE VERSION [--accept-agreements] [--execute]</code>: নির্দিষ্ট প্যাকেজ আপডেটের সংরক্ষিত কমান্ড; বর্তমানে বন্ধ, প্রস্থান কোড 2। সক্রিয় হলে সদ্য খুঁজে পাওয়া নির্দিষ্ট ID, উৎস ও সংস্করণের পূর্বরূপ দেখায়। সেই নির্বাচন পর্যালোচনার পর চালাতে উভয় সুইচ প্রয়োজন; সুরক্ষা যাচাই আবার হয় এবং অনুরোধ জার্নালে লেখা হয়। আউটপুট JSON; যোগ্যতা ও সম্পাদনের ফল স্পষ্ট থাকে। পুনরাবৃত্ত বা অজানা ফ্ল্যাগ প্রত্যাখ্যাত হয়। ব্যাপক আপগ্রেড বা পরোক্ষভাবে চুক্তি গ্রহণ করে না।",
    "cli_ref_third_party_recover": "<code>third-party-update-recover</code>: অপেক্ষমাণ নির্দিষ্ট সংস্করণের অবস্থা মিলিয়ে দেখার সংরক্ষিত কমান্ড; বর্তমানে বন্ধ, প্রস্থান কোড 2। সক্রিয় হলে স্থানীয় ThirdPartyUpdates জার্নাল পড়ে ও ইনস্টল আবার চেষ্টা না করে অবস্থা যাচাই করে। আউটপুট JSON; অপেক্ষমাণ রেকর্ড না থাকলে বা অবস্থা যাচাই হলে 0, অমীমাংসিত প্রমাণে 3, বাতিলে 130। কোনো অপশন নেয় না।",
    "cli_ref_validate_native": "<code>validate-native RECIPE_ID SCENARIO_SUFFIX|all OUTPUT_DIR --disposable MACHINE_NAME</code>: ইচ্ছাকৃত ত্রুটি তৈরি করে যাচাই; শুধু-পঠন রোগনির্ণয় বা পূর্বরূপ নয়। পরীক্ষার পর ফেলে দেওয়ার উপযোগী Windows কম্পিউটারে প্রশাসকের অনুমতি, কম্পিউটারের হুবহু নাম ও <code>KILLERBENCH_DISPOSABLE=yes-this-machine-is-disposable</code> প্রয়োজন। কখনো ডেভেলপমেন্ট বা গ্রাহকের কম্পিউটার ব্যবহার করবেন না। রেসিপির নির্বাচিত ইনস্টল করা পরিস্থিতি বা সব পরিস্থিতি চালায়, আগের অবস্থা ফেরানোর চেষ্টা করে এবং OUTPUT_DIR-এ রেকর্ড ও পরীক্ষার ফাইল লেখে। আউটপুট টেক্সট; কোনো পরিস্থিতি ব্যর্থ হলে 3, একটিও ব্যর্থ না হলে 0 (তবু বাধাপ্রাপ্ত পরিস্থিতি থাকতে পারে), সুরক্ষা শর্ত না মানলে বা ভুল ইনপুটে 2, বাতিলে 130। প্রতিটি ফল ও পুনরুদ্ধারের রেকর্ড পরীক্ষা করুন; শুধু প্রস্থান কোড 0 যাচাইয়ের ছাড়পত্র নয়।",
    "cli_ref_forms": "অতিরিক্ত গ্রহণযোগ্য অপশন ও ওয়ার্কফ্লোর রূপ",
    "cli_ref_forms_intro": "নিচের বিভাগভিত্তিক নির্দেশিকায় সব পাবলিক কমান্ড আছে। এই বিস্তৃত রূপগুলোতে সংক্ষিপ্ত তালিকায় সহজে চোখ এড়ানো অপশনগুলোও রাখা হয়েছে।",
    "cli_ref_bitlocker_form": "<code>bitlocker-plan [--volume C:] [--operation Inspect|BackupRecovery|Encrypt|ResumeProtection] [--encryption Aes128|Aes256|XtsAes128|XtsAes256] [--used-space-only] [--backup File|ActiveDirectory|EntraId] [--backup-file PATH] [--inspect]</code>: শুধু টেক্সটে পরিকল্পনা করে। <code>--inspect</code> নির্বাচিত ভলিউম পড়ে; সুরক্ষার সেটিং বদলায় না। আসল অপারেশনের জন্য নির্দিষ্ট সুরক্ষিত কমান্ড ব্যবহার করুন।",
    "cli_ref_debloat_form": "<code>debloat-review --area AREA [--area AREA ...] [--all-profiles] [--keep-office-culture CULTURE] [--sleep-ac MINUTES --sleep-dc MINUTES --display-ac MINUTES --display-dc MINUTES] [--apply-high-performance|--apply-power-timers|--disable-hibernation] [--json]</code>: ডিফল্টভাবে পর্যালোচনা করে। প্রতিটি স্পষ্ট পাওয়ার সুইচ অতিরিক্ত <code>--execute</code> ছাড়াই পরিবর্তন করে। ঠিক একটি সম্পাদন সুইচ এবং কেবল তার সংশ্লিষ্ট এলাকা বাছুন: HighPerformancePower, SleepAndDisplayTimers বা Hibernation। চারটি টাইমারের মান একসঙ্গে দিতে হয়, প্রতিটি 0 থেকে 1440 মিনিট; শূন্য মানে কখনো নয়। অপেক্ষমাণ পাওয়ার রেকর্ড থাকলে পরিবর্তন আবার না করে অবস্থা মিলিয়ে দেখে। ডিফল্ট টেক্সট, <code>--json</code> দিলে JSON; বাধাপ্রাপ্ত বা অযাচাইকৃত প্রমাণ স্পষ্ট থাকে।",
    "cli_ref_depot_form": "<code>depot-review [--microsoft-365] [--onedrive] [--teams] [--chrome] [--acrobat-reader] [--zoom] [--7zip] [--windows-updates] [--computer-name] [--local-admin] [--admin-review] [--browser-extensions] [--cleanup] [--edge] [--privacy] [--taskbar] [--start-menu] [--notifications] [--json]</code>: অন্তত একটি অ্যাপ বা কনফিগারেশন গ্রুপ বাছুন। শুধু টেক্সট বা JSON-এ প্রাথমিক সেটআপ পর্যালোচনা; ইনস্টলার ডাউনলোড, অ্যাকাউন্ট তৈরি বা কনফিগারেশন পরিবর্তন করে না।",
    "cli_ref_audio_form": "<code>device-check audio [--knowledge PACK_PATH ...] [--direction output|input] [--role console|multimedia|communications]</code>: ঐচ্ছিক দিক ও ভূমিকার ফিল্টার শুধু অডিওতে প্রযোজ্য। সর্বোচ্চ 32 প্যাকের প্রতিটির জন্য <code>--knowledge PATH</code> পুনরাবৃত্তি করুন। শুধু-পঠন JSON; কোনো ফিল্টারই ডিফল্ট অডিও এন্ডপয়েন্ট বদলায় না।",
    "cli_ref_privacy_form": "<code>privacy-plan [--select AREA ...] [--inspect]</code>: টেক্সট পূর্বরূপ বা রেজিস্ট্রির শুধু-পঠন পরীক্ষা। <code>privacy-setting</code> ও <code>privacy-clipboard-history</code>-এর action, recover ও undo-এর ছয়টি রূপই <code>--journal-folder PATH</code> গ্রহণ করে। সম্পাদন ও পুনরুদ্ধারে একই ফোল্ডার ব্যবহার করুন। <code>--execute</code> না থাকলে action ও undo কেবল পূর্বরূপ দেখায়; recover কখনো পরিবর্তন আবার করে না।",
    "cli_ref_update_search_form": "<code>update-search [--source Configured|WindowsUpdate|MicrosoftUpdate] [--drivers] [--no-software] [--filter TITLE] [--downloaded-only] [--classification GUID] [--product GUID]</code>: শুধু-পঠন JSON অনুসন্ধান ও হুবহু মিলে যাওয়া পরিচয়। উৎস নির্বাচন ডাউনলোড বা ইনস্টলের অনুমতি দেয় না।",
    "cli_ref_update_plan_form": "<code>update-plan --select GUID:REVISION [--select GUID:REVISION ...] [--source Configured|WindowsUpdate|MicrosoftUpdate] [--drivers] [--no-software] [--allow-restart-required] [--allow-feature-upgrade] [--json] [--execute]</code>: পূর্বরূপের আগে নতুন করে অনুসন্ধান হয়। ফিচার আপগ্রেডের জন্য অনুমতির উভয় ফ্ল্যাগ প্রয়োজন এবং শুধু সেটিই বাছতে হবে। ইনস্টলের জন্য <code>--execute</code> ও সুরক্ষা শর্ত অনুযায়ী যোগ্যতা প্রয়োজন। <code>update-recover</code> কোনো অপশন নেয় না এবং কখনো আপডেট ইনস্টল করে না।",
    "cli_ref_workflow_form": "<code>workflow WORKFLOW [--recipes ID[,ID]] [--auto-repair] [--report OUTPUT.html|OUTPUT.txt] [--json]</code>: বৈধ নামের জন্য <code>workflows</code>, অনুমোদিত রেসিপির ID-এর জন্য <code>recipes WORKFLOW</code> ব্যবহার করুন। নির্দিষ্ট ওয়ার্কফ্লো <code>--auto-repair</code> সমর্থন ও গ্রহণ না করলে শুধু-পঠন; প্রতিটি মেরামতের জন্য তবুও যোগ্যতা ও যাচাই প্রয়োজন। Common-problems/full-scan স্বয়ংক্রিয় মেরামত প্রত্যাখ্যান করে। <code>--set KEY=VALUE</code> পরিকল্পনা শুধু-পঠন এবং রেসিপি নির্বাচন, পরিসর নির্বাচন বা স্বয়ংক্রিয় মেরামতের সঙ্গে মেশানো যায় না। প্রতিবেদনের .html বা .txt পথ আগে থেকে থাকা চলবে না।",
    "cli_ref_workflow_scopes": "<code>workflow background-transfers [--all-users] [--json]</code>: সীমিত ট্রান্সফার পরীক্ষা, স্বয়ংক্রিয় মেরামত নেই। Installed-apps <code>--current-user</code> গ্রহণ করে; app-packages <code>--all-users</code> ও <code>--include-provisioned</code> গ্রহণ করে। Defender <code>--skip-tpm</code>, <code>--skip-secure-boot</code> ও <code>--skip-virtualization</code> গ্রহণ করে। available-updates ওয়ার্কফ্লো <code>--source Configured|WindowsUpdate|MicrosoftUpdate</code>, <code>--drivers</code> ও <code>--no-software</code> গ্রহণ করে; বর্তমান রিলিজে এর <code>--third-party</code> অপশন বন্ধ।",
    "cli_ref_exit_limits": "প্রস্থান কোড সংশ্লিষ্ট কমান্ডের ফলের সঙ্গে মিলিয়ে বুঝুন: সফল ক্যাটালগ পড়া, পুরোনো তথ্য আমদানি, পরিকল্পনা রপ্তানি বা বিশ্লেষণ কম্পিউটারের সুস্থতার রায় নয়। symptom-এর প্রস্থান কোড 5 মানে মূল সমস্যা দূর হওয়া নিশ্চিত নয়। নেটিভ যাচাই বাধাপ্রাপ্ত পরিস্থিতি থাকলেও 0 দিতে পারে। অসম্পূর্ণ প্রমাণ অসম্পূর্ণই থাকবে। <code>recover</code> নামের কমান্ড রেকর্ড করা অপারেশনের অবস্থা মিলিয়ে দেখে, সেটি আবার চেষ্টা করার অনুমতি দেয় না।",
    "cli_ref_full_link": "প্রতিটি কমান্ডের গ্রহণযোগ্য সিনট্যাক্স, আউটপুট, সীমা ও সম্পাদনের শর্ত জানতে <a href=\"../help.html#cli\">সহায়তা পাতার পূর্ণ কমান্ড লাইন নির্দেশিকা</a> খুলুন। এই পাতায় প্রধান ওয়ার্কফ্লোগুলোর পরিচয় আছে।"
  },
  "cs": {
    "cli_ref_discovery": "Vyhledání příkazů, třídění problémů a místní důkazy",
    "cli_ref_conventions": "Před každý příkaz níže napište <code>killerbench-cli</code>. Cesty a text s mezerami uzavřete do uvozovek. Hranaté závorky označují nepovinné argumenty, svislá čára odděluje alternativy. U <code>...</code> opakujte celou volbu. Volby patří jen k uvedenému příkazu. Strojově čitelný seznam názvů, včetně názvů vyhrazených pro pozdější vydání, získáte pomocí <code>capabilities</code>. Nápovědu v konzoli zobrazíte pomocí <code>help</code>, <code>--help</code>, <code>-h</code> nebo bez argumentů.",
    "cli_ref_exceptions": "Obecné pravidlo náhledu má výjimky: <code>symptom run --repair</code>, <code>workflow --auto-repair</code> a tři přepínače napájení příkazu <code>debloat-review</code> povolují popsané změny bez <code>--execute</code>. <code>validate-native</code> záměrně vyvolává chyby pouze v chráněném jednorázovém prostředí. Export balíčků, uložené plány, žurnály a zprávy také zapisují místní soubory. JSON je dostupný jen tam, kde je uveden; vyhledání a ověření balíčků, analýza prostého textu a některé náhledy používají text. Průběh a oznámení o schopnostech se mohou objevit na standardním chybovém výstupu i při úspěchu.",
    "cli_ref_profile_backup_limits": "<code>profiles --backup-to</code> podporuje nezašifrované položky profilů. Zdroj šifrovaný pomocí EFS je odmítnut ještě před vytvořením cíle zálohy.",
    "cli_ref_capabilities": "<code>capabilities [--json]</code>: V obou podobách vrací JSON: <code>schemaVersion</code> (1), <code>version</code> sestavení a seřazené jedinečné <code>commands</code> (řetězce). Neprovádí diagnostiku ani opravy. Přijímá jen nepovinné <code>--json</code>; návratový kód 0 při úspěchu, 2 při jiných argumentech. Uvedený název nedokládá nativní podporu ani dostupnost ve vydání.",
    "cli_ref_pack": "<code>pack list | pack export PACK_ID OUTPUT.json | pack validate PACK.json</code>: Vypíše vestavěné balíčky, označení schopností receptů a primitiva; exportuje vestavěný balíček do dosud neexistujícího souboru; nebo ověří místní balíček proti knihovně primitiv Windows. Textový výstup, žádný recept se nespouští. Export vytvoří nadřazené adresáře. Návratové kódy: 0 úspěch, 2 neplatné argumenty, neznámé ID nebo existující výstup, 3 neplatný či nečitelný balíček.",
    "cli_ref_symptom": "<code>symptom list | symptom search TEXT | symptom run SYMPTOM_ID [--repair] [--explicit] [--option NAME=VALUE]... [--answer NODE=KEY]... [--json]</code>: Vypíše nebo vyhledá podporovaná ID příznaků a spustí jeden omezený rozhodovací strom. Výchozí běh pouze zjišťuje stav. <code>--repair</code> povoluje automatické recepty balíčků s novými kontrolami; <code>--explicit</code> navíc potvrzuje recepty vyžadující výslovné volby a vyžaduje <code>--repair</code>. Každý recept se použije nejvýše jednou; výchozí meze jsou 40 kroků, 10 oprav a 30 minut. Nezodpovězené otázky zůstávají otevřené. Běh zapisuje místní žurnál Triage a vrací text nebo JSON. Kódy: 0 vyřešeno nebo vyloučeno, 3 nevyřešeno či blokováno, 4 nutný restart, 5 oprava součásti ověřena bez potvrzení odstranění příznaku, 130 zrušeno. Hledání bez shody vrací 3, neplatný vstup 2.",
    "cli_ref_investigate": "<code>investigate FILE_PATH [--json]</code>: Použije podporovaná pravidla vyhodnocení důkazů na místní textový protokol, uložený archiv EVTX nebo export událostí Windows ve formátu XML; přidá vysvětlení, odkazy a další kroky. Textový import čte nejvýše 1,000,000 znaků a 10,000 zpracovaných položek. EVTX vyžaduje Windows a ponechá nejnovějších 200 záznamů; XML prvních 200 v pořadí souboru. Ani jeden import událostí nefiltruje podle data a historické důkazy nedokládají aktuální stav počítače. Analýza má limit pro zrušení 15 sekund. Výchozí výstup je text, s <code>--json</code> JSON. Kódy: 0 analýza dokončena, 3 částečné důkazy, 1 nečitelný či nepodporovaný vstup, 2 neplatné argumenty, 130 zrušení nebo časový limit. Žádné opravy.",
    "cli_ref_analyze": "<code>analyze TEXT_LOG_PATH [--json]</code>: Z textového protokolu získá pozorování různých kódů, aniž určí příčinu nebo něco změní. Čte nejvýše 1,000,000 znaků, ponechá nejvýše 256 kódů a osm odkazů na kód; limit pro zrušení je 15 sekund. Výchozí text, s <code>--json</code> JSON. Kódy: 0 úplná analýza, 3 zkrácení, 1 chyba vstupu, 2 neplatné argumenty, 130 zrušení nebo časový limit.",
    "cli_ref_duplicate_files": "<code>duplicate-files FOLDER [--min-bytes N] [--max-files N] [--report]</code>: Kontrola duplicit v jedné místní složce pomocí SHA-256, pouze pro čtení. Výchozí minimum je jeden bajt a limit 10,000 souborů; minimum může být nula, limit souborů 1 až 100,000. Celkové hašování je omezeno na 100 GiB. Výchozí JSON, s <code>--report</code> text; oba výstupy mohou odhalit cesty k souborům. Žádný soubor se nevybírá ke smazání. Kódy: 0 úplné, 3 neúplné, 1 chyba kontroly/vstupu, 2 chybné volby, 130 zrušeno.",
    "cli_ref_large_files": "<code>large-files FOLDER [--min-bytes N] [--max-files N] [--limit N] [--report]</code>: Kontrola velikostí v jedné místní složce, pouze pro čtení. Výchozí minimum 100 MiB, 10,000 zkoumaných souborů a 500 uchovaných výsledků. Minimum musí být kladné; limit souborů 1 až 100,000 a výsledků 1 až 10,000. Výchozí JSON, s <code>--report</code> text; výstup obsahuje cesty. Kódy: 0 úplné, 3 neúplné, 1 chyba kontroly/vstupu, 2 chybné volby, 130 zrušeno. Žádné čištění.",
    "cli_ref_file_limits": "Obě kontroly složek přeskakují body změny zpracování (reparse points) a omezují průchod: výchozí limity jsou 10,000 adresářů, 1,024 čekajících adresářů, hloubka 128 a 30 sekund. Nepřístupný obsah nebo dosažení limitu průchodu, hašování, souborů či výsledků znamená neúplnost. Jde o meze pokrytí, nikoli důkaz bezpečnosti vynechaných souborů.",
    "cli_ref_debloat_recover": "<code>debloat-recover power-plan|power-timers|hibernation --folder PATH [--json]</code>: Ověří a sjednotí stav jednoho typu čekající operace napájení podle úplné cesty složky žurnálu. Vyberte stejnou složku s čekajícím záznamem, obvykle <code>%LOCALAPPDATA%\\KillerBench\\Debloat</code>. Vždy vrací JSON, s <code>--json</code> i bez něj; průběh jde na standardní chybový výstup. Změnu napájení neopakuje. Vyřešené místní záznamy lze archivovat. Kódy: 0 žádný čekající záznam nebo ověřený stav, 3 nevyřešené důkazy, 1 chyba souboru/poskytovatele, 2 neplatné argumenty nebo relativní/chybějící cesta složky, 130 zrušeno. Volba <code>--execute</code> neexistuje.",
    "cli_ref_gated": "Omezení vydání a nativní ověřování v jednorázovém prostředí",
    "cli_ref_third_party_updates": "<code>third-party-updates</code>: Vyhrazené zjišťování aktualizací aplikací přes Microsoft.WinGet.Client, pouze pro čtení. V aktuálním vydání vypnuto; bez zjišťování vrací kód 2 a oznámení o dostupnosti v KillerBench 1.1. Po zapnutí vrací JSON; úplné dostupné zjištění má kód 0, neúplné či nedostupné 3, chyba poskytovatele 1, zrušení 130.",
    "cli_ref_third_party_update": "<code>third-party-update ID SOURCE VERSION [--accept-agreements] [--execute]</code>: Vyhrazená aktualizace přesně určeného balíčku; nyní vypnuta s kódem 2. Po zapnutí standardně zobrazí náhled nově zjištěného přesného ID, zdroje a verze. Po kontrole výběru vyžaduje spuštění oba přepínače, opakuje bezpečnostní kontroly a zapisuje požadavek do žurnálu. Výstup JSON; způsobilost i výsledky provedení zůstávají výslovně uvedeny. Duplicitní či neznámé přepínače odmítá. Žádný plošný upgrade ani implicitní přijetí smluv.",
    "cli_ref_third_party_recover": "<code>third-party-update-recover</code>: Vyhrazené ověření čekající přesné verze; nyní vypnuto s kódem 2. Po zapnutí čte místní žurnál ThirdPartyUpdates a ověří stav bez opakování instalace. Výstup JSON; 0 žádný čekající záznam nebo ověřený stav, 3 nevyřešené důkazy, 130 zrušení. Žádné volby.",
    "cli_ref_validate_native": "<code>validate-native RECIPE_ID SCENARIO_SUFFIX|all OUTPUT_DIR --disposable MACHINE_NAME</code>: Ověřování záměrným vyvoláním chyb, nikoli diagnostika pouze pro čtení či náhled. Na jednorázovém počítači Windows vyžaduje oprávnění správce, přesný název počítače a <code>KILLERBENCH_DISPOSABLE=yes-this-machine-is-disposable</code>. Nikdy nepoužívejte vývojový ani zákaznický počítač. Spustí vybraný nainstalovaný scénář nebo všechny scénáře receptu, pokusí se obnovit stav a do OUTPUT_DIR zapíše záznamy a artefakty. Textový výstup; 3 při selhání některého scénáře, 0 pokud žádný neselhal (mohou zůstat blokované scénáře), 2 při odmítnutí ochrannými kontrolami nebo neplatném vstupu, 130 při zrušení. Zkontrolujte všechny výsledky i záznamy obnovy; samotný kód 0 neznamená schválené ověření.",
    "cli_ref_forms": "Další přijímané volby a podoby pracovních postupů",
    "cli_ref_forms_intro": "Níže rozdělená příručka pokrývá všechny veřejné příkazy. Rozšířené podoby zachovávají volby, které lze v kratších položkách snadno přehlédnout.",
    "cli_ref_bitlocker_form": "<code>bitlocker-plan [--volume C:] [--operation Inspect|BackupRecovery|Encrypt|ResumeProtection] [--encryption Aes128|Aes256|XtsAes128|XtsAes256] [--used-space-only] [--backup File|ActiveDirectory|EntraId] [--backup-file PATH] [--inspect]</code>: Jen plán v textu. <code>--inspect</code> přečte vybraný svazek, nemění nastavení ochrany. Ke skutečné operaci použijte příslušný chráněný příkaz.",
    "cli_ref_debloat_form": "<code>debloat-review --area AREA [--area AREA ...] [--all-profiles] [--keep-office-culture CULTURE] [--sleep-ac MINUTES --sleep-dc MINUTES --display-ac MINUTES --display-dc MINUTES] [--apply-high-performance|--apply-power-timers|--disable-hibernation] [--json]</code>: Standardně jen kontrola. Každý výslovný přepínač napájení provede změnu bez dalšího <code>--execute</code>. Zvolte právě jeden přepínač provedení a pouze odpovídající oblast: HighPerformancePower, SleepAndDisplayTimers nebo Hibernation. Všechny čtyři časovače musí být zadány společně, každý 0 až 1440 minut; nula znamená Nikdy. Existující čekající záznamy se ověří místo opakování změny. Výchozí text, s <code>--json</code> JSON; blokované a neověřené důkazy zůstávají výslovně označeny.",
    "cli_ref_depot_form": "<code>depot-review [--microsoft-365] [--onedrive] [--teams] [--chrome] [--acrobat-reader] [--zoom] [--7zip] [--windows-updates] [--computer-name] [--local-admin] [--admin-review] [--browser-extensions] [--cleanup] [--edge] [--privacy] [--taskbar] [--start-menu] [--notifications] [--json]</code>: Vyberte alespoň jednu aplikaci nebo skupinu nastavení. Jen vstupní kontrola v textu či JSON; žádné stahování instalátoru, vytváření účtů ani změny nastavení.",
    "cli_ref_audio_form": "<code>device-check audio [--knowledge PACK_PATH ...] [--direction output|input] [--role console|multimedia|communications]</code>: Nepovinné filtry směru a role platí jen pro zvuk. Opakujte <code>--knowledge PATH</code> pro každý z nejvýše 32 balíčků. JSON pouze pro čtení; žádný filtr nemění výchozí zvukový koncový bod.",
    "cli_ref_privacy_form": "<code>privacy-plan [--select AREA ...] [--inspect]</code>: Textový náhled nebo kontrola registru pouze pro čtení. Všech šest podob action, recover a undo pro <code>privacy-setting</code> a <code>privacy-clipboard-history</code> přijímá také <code>--journal-folder PATH</code>. Pro provedení i obnovu použijte stejnou složku. Akce a vrácení změn jsou bez <code>--execute</code> jen náhledy; obnova změnu nikdy neopakuje.",
    "cli_ref_update_search_form": "<code>update-search [--source Configured|WindowsUpdate|MicrosoftUpdate] [--drivers] [--no-software] [--filter TITLE] [--downloaded-only] [--classification GUID] [--product GUID]</code>: Zjišťování pouze pro čtení s výstupem JSON a přesně odpovídajícími identitami. Výběr zdroje nepovoluje stahování ani instalaci.",
    "cli_ref_update_plan_form": "<code>update-plan --select GUID:REVISION [--select GUID:REVISION ...] [--source Configured|WindowsUpdate|MicrosoftUpdate] [--drivers] [--no-software] [--allow-restart-required] [--allow-feature-upgrade] [--json] [--execute]</code>: Náhledu předchází nové zjišťování. Upgrade funkcí vyžaduje oba povolovací přepínače a musí být vybrán samostatně. Instalace vyžaduje <code>--execute</code> a způsobilost ověřenou ochrannými kontrolami. <code>update-recover</code> nepřijímá volby a nikdy neinstaluje aktualizace.",
    "cli_ref_workflow_form": "<code>workflow WORKFLOW [--recipes ID[,ID]] [--auto-repair] [--report OUTPUT.html|OUTPUT.txt] [--json]</code>: Platné názvy získáte pomocí <code>workflows</code>, povolená ID receptů pomocí <code>recipes WORKFLOW</code>. Pouze pro čtení, pokud příslušný postup nepodporuje a neobdrží <code>--auto-repair</code>; každá oprava stále vyžaduje způsobilost a ověření. Common-problems/full-scan odmítá automatické opravy. Plány <code>--set KEY=VALUE</code> zůstávají pouze pro čtení a nelze je kombinovat s výběrem receptů, rozsahu nebo automatickými opravami. Zpráva vyžaduje dosud neexistující cestu .html nebo .txt.",
    "cli_ref_workflow_scopes": "<code>workflow background-transfers [--all-users] [--json]</code>: Omezená kontrola přenosů bez automatických oprav. Installed-apps přijímá <code>--current-user</code>; app-packages přijímá <code>--all-users</code> a <code>--include-provisioned</code>. Defender přijímá <code>--skip-tpm</code>, <code>--skip-secure-boot</code> a <code>--skip-virtualization</code>. Postup available-updates přijímá <code>--source Configured|WindowsUpdate|MicrosoftUpdate</code>, <code>--drivers</code> a <code>--no-software</code>; jeho volba <code>--third-party</code> je v aktuálním vydání vypnutá.",
    "cli_ref_exit_limits": "Návratové kódy vykládejte spolu s výsledkem příkazu: úspěšné načtení katalogu, import historie, export plánu či analýza nejsou posouzením stavu počítače. Kód 5 příkazu symptom znamená, že odstranění původního problému není potvrzeno. Nativní ověřování může vrátit 0 i s blokovanými scénáři. Neúplné důkazy musí zůstat neúplné. Příkazy <code>recover</code> ověřují stav zaznamenané operace a nepovolují její opakování.",
    "cli_ref_full_link": "Všechny příkazy, přijímanou syntaxi, výstupy, limity a podmínky provedení najdete v <a href=\"../help.html#cli\">úplné příručce příkazového řádku na stránce nápovědy</a>. Tato stránka představuje hlavní pracovní postupy."
  },
  "de": {
    "cli_ref_discovery": "Befehle finden, Probleme eingrenzen und lokale Nachweise",
    "cli_ref_conventions": "Stellen Sie jedem folgenden Befehl <code>killerbench-cli</code> voran. Setzen Sie Pfade oder Text mit Leerzeichen in Anführungszeichen. Eckige Klammern kennzeichnen optionale Argumente, ein senkrechter Strich trennt Alternativen. Bei <code>...</code> wiederholen Sie die gesamte Option. Optionen gelten nur für den genannten Befehl. <code>capabilities</code> liefert die maschinenlesbare Namensliste, einschließlich reservierter Namen für spätere Freigaben. Konsolenhilfe erhalten Sie mit <code>help</code>, <code>--help</code>, <code>-h</code> oder ohne Argumente.",
    "cli_ref_exceptions": "Die allgemeine Vorschauregel hat befehlsspezifische Ausnahmen: <code>symptom run --repair</code>, <code>workflow --auto-repair</code> und die drei Energieoptionen von <code>debloat-review</code> erlauben ihre dokumentierten Änderungen ohne <code>--execute</code>. <code>validate-native</code> erzeugt Fehler nur in einer abgesicherten, verwerfbaren Testumgebung. Paketexport, gespeicherte Pläne, Journale und Berichte schreiben ebenfalls lokale Dateien. JSON steht nur dort zur Verfügung, wo es dokumentiert ist; Paketsuche und Paketprüfung, Klartextanalyse und einige Vorschauen verwenden Text. Fortschritts- und Funktionshinweise können auch bei Erfolg auf der Standardfehlerausgabe erscheinen.",
    "cli_ref_profile_backup_limits": "<code>profiles --backup-to</code> unterstützt unverschlüsselte Profileinträge. Eine EFS-verschlüsselte Quelle wird abgelehnt, bevor ein Sicherungsziel erstellt wird.",
    "cli_ref_capabilities": "<code>capabilities [--json]</code>: Liefert in beiden Formen JSON: <code>schemaVersion</code> (1), die Assembly-<code>version</code> und sortierte, eindeutige <code>commands</code> (Zeichenfolgen). Keine Diagnose oder Reparatur. Akzeptiert nur das optionale <code>--json</code>; Rückgabecode 0 bei Erfolg, 2 bei anderen Argumenten. Ein gelisteter Name belegt weder native Unterstützung noch Verfügbarkeit in dieser Version.",
    "cli_ref_pack": "<code>pack list | pack export PACK_ID OUTPUT.json | pack validate PACK.json</code>: Listet integrierte Pakete, Funktionskennzeichnungen der Rezepte und Primitive auf, exportiert ein integriertes Paket an einen noch nicht vorhandenen Ausgabepfad oder prüft ein lokales Paket anhand der Windows-Primitivbibliothek. Textausgabe, keine Rezepte werden ausgeführt. Der Export erstellt übergeordnete Verzeichnisse. Rückgabecodes: 0 Erfolg, 2 ungültige Argumente, unbekannte IDs oder vorhandene Ausgabe, 3 ungültige oder unlesbare Pakete.",
    "cli_ref_symptom": "<code>symptom list | symptom search TEXT | symptom run SYMPTOM_ID [--repair] [--explicit] [--option NAME=VALUE]... [--answer NODE=KEY]... [--json]</code>: Listet oder sucht unterstützte Symptom-IDs und durchläuft einen begrenzten Entscheidungsbaum. Standardmäßig wird nur geprüft. <code>--repair</code> erlaubt automatische Paketrezepte mit erneuten Prüfungen; <code>--explicit</code> bestätigt zusätzlich Rezepte mit ausdrücklich erforderlichen Optionen und setzt <code>--repair</code> voraus. Jedes Rezept wird höchstens einmal angewendet; Standardgrenzen sind 40 Schritte, 10 Reparaturen und 30 Minuten. Unbeantwortete Fragen bleiben offen. Der Lauf schreibt ein lokales Triage-Journal und liefert Text oder JSON. Rückgabecodes: 0 behoben oder ausgeschlossen, 3 ungelöst oder blockiert, 4 Neustart erforderlich, 5 Komponentenreparatur bestätigt, aber Beseitigung des Symptoms unbestätigt, 130 abgebrochen. Suche ohne Treffer liefert 3, ungültige Eingabe 2.",
    "cli_ref_investigate": "<code>investigate FILE_PATH [--json]</code>: Wendet unterstützte Nachweisregeln auf ein lokales Textprotokoll, ein gespeichertes EVTX-Archiv oder ein exportiertes Windows-Ereignisdokument im XML-Format an, mit Erklärungen, Verweisen und nächsten Schritten. Textimporte lesen höchstens 1,000,000 Zeichen und 10,000 geparste Einträge. EVTX erfordert Windows und behält die neuesten 200 Datensätze; XML die ersten 200 in Dateireihenfolge. Beide Ereignisimporte verzichten auf einen Datumsfilter; historische Nachweise belegen nicht den aktuellen Rechnerzustand. Die Analyse hat ein Abbruchzeitlimit von 15 Sekunden. Standardmäßig Text, mit <code>--json</code> JSON. Codes: 0 Analyse abgeschlossen, 3 teilweise Nachweise, 1 unlesbare oder nicht unterstützte Eingabe, 2 ungültige Argumente, 130 Abbruch oder Zeitüberschreitung. Keine Reparatur.",
    "cli_ref_analyze": "<code>analyze TEXT_LOG_PATH [--json]</code>: Extrahiert unterschiedliche Codebeobachtungen aus einem Textprotokoll, ohne Ursachen zu diagnostizieren oder Änderungen vorzunehmen. Liest höchstens 1,000,000 Zeichen, behält bis zu 256 Codes und acht Verweise pro Code; Abbruchzeitlimit 15 Sekunden. Standardmäßig Text, mit <code>--json</code> JSON. Codes: 0 vollständige Analyse, 3 Kürzung, 1 Eingabefehler, 2 ungültige Argumente, 130 Abbruch oder Zeitüberschreitung.",
    "cli_ref_duplicate_files": "<code>duplicate-files FOLDER [--min-bytes N] [--max-files N] [--report]</code>: Schreibgeschützte Duplikatprüfung eines lokalen Ordners mit SHA-256. Standard: mindestens ein Byte, 10,000 Dateien; das Minimum darf null sein, die Dateigrenze 1 bis 100,000. Insgesamt werden höchstens 100 GiB gehasht. Standardmäßig JSON, mit <code>--report</code> Text; beide Ausgaben können Dateipfade offenlegen. Keine Datei wird zum Löschen ausgewählt. Codes: 0 vollständig, 3 unvollständig, 1 Scan-/Eingabefehler, 2 fehlerhafte Optionen, 130 abgebrochen.",
    "cli_ref_large_files": "<code>large-files FOLDER [--min-bytes N] [--max-files N] [--limit N] [--report]</code>: Schreibgeschützte Größenprüfung eines lokalen Ordners. Standard: mindestens 100 MiB, 10,000 untersuchte Dateien und 500 gespeicherte Ergebnisse. Das Minimum muss positiv sein; Dateigrenze 1 bis 100,000, Ergebnisgrenze 1 bis 10,000. Standardmäßig JSON, mit <code>--report</code> Text; die Ausgabe enthält Dateipfade. Codes: 0 vollständig, 3 unvollständig, 1 Scan-/Eingabefehler, 2 fehlerhafte Optionen, 130 abgebrochen. Keine Bereinigung.",
    "cli_ref_file_limits": "Beide Ordnerprüfungen überspringen Reparse Points und begrenzen den Verzeichnisdurchlauf: standardmäßig 10,000 Verzeichnisse, 1,024 ausstehende Verzeichnisse, Tiefe 128 und 30 Sekunden. Unzugängliche Inhalte oder erreichte Grenzen für Durchlauf, Hashing, Dateien oder Ergebnisse bedeuten unvollständige Ergebnisse. Dies sind Abdeckungsgrenzen, keine Sicherheitsnachweise für ausgelassene Dateien.",
    "cli_ref_debloat_recover": "<code>debloat-recover power-plan|power-timers|hibernation --folder PATH [--json]</code>: Gleicht einen Typ ausstehender Energieoperationen anhand des vollständigen Journalordnerpfads ab. Wählen Sie denselben Ordner mit dem ausstehenden Eintrag, normalerweise <code>%LOCALAPPDATA%\\KillerBench\\Debloat</code>. Liefert immer JSON, mit oder ohne <code>--json</code>; Fortschritt geht an die Standardfehlerausgabe. Wiederholt keine Energieänderung. Erledigte lokale Einträge können archiviert werden. Codes: 0 kein ausstehender Eintrag oder Zustand bestätigt, 3 ungeklärte Nachweise, 1 Datei-/Anbieterfehler, 2 ungültige Argumente oder relativer/fehlender Ordnerpfad, 130 abgebrochen. Keine Option <code>--execute</code>.",
    "cli_ref_gated": "Freigabegrenzen und native Validierung in verwerfbaren Testumgebungen",
    "cli_ref_third_party_updates": "<code>third-party-updates</code>: Reservierte, schreibgeschützte Suche nach Anwendungsupdates mit Microsoft.WinGet.Client. In dieser Version deaktiviert; liefert ohne Suche Code 2 mit dem Verfügbarkeitshinweis für KillerBench 1.1. Nach Aktivierung JSON; Codes: 0 vollständige verfügbare Suche, 3 unvollständige oder nicht verfügbare Suche, 1 Anbieterfehler, 130 Abbruch.",
    "cli_ref_third_party_update": "<code>third-party-update ID SOURCE VERSION [--accept-agreements] [--execute]</code>: Reserviertes Update eines exakt bestimmten Pakets; derzeit deaktiviert mit Code 2. Nach Aktivierung standardmäßig Vorschau der frisch ermittelten exakten ID, Quelle und Version. Die Ausführung erfordert nach Prüfung der Auswahl beide Schalter, wiederholt Schutzprüfungen und protokolliert den Auftrag. JSON-Ausgabe; Eignung und Ausführungsergebnisse bleiben ausdrücklich ausgewiesen. Doppelte oder unbekannte Flags werden abgelehnt. Kein pauschales Upgrade und keine stillschweigende Zustimmung zu Vereinbarungen.",
    "cli_ref_third_party_recover": "<code>third-party-update-recover</code>: Reservierter Abgleich einer ausstehenden exakten Version; derzeit deaktiviert mit Code 2. Nach Aktivierung liest der Befehl das lokale ThirdPartyUpdates-Journal und prüft den Zustand ohne erneuten Installationsversuch. JSON-Ausgabe; 0 kein ausstehender Eintrag oder Zustand bestätigt, 3 ungeklärte Nachweise, 130 Abbruch. Keine Optionen.",
    "cli_ref_validate_native": "<code>validate-native RECIPE_ID SCENARIO_SUFFIX|all OUTPUT_DIR --disposable MACHINE_NAME</code>: Validierung durch gezielte Fehlereinbringung, keine schreibgeschützte Diagnose oder Vorschau. Erfordert auf einem verwerfbaren Windows-Testrechner Administratorrechte, den exakten Rechnernamen und <code>KILLERBENCH_DISPOSABLE=yes-this-machine-is-disposable</code>. Niemals einen Entwicklungs- oder Kundenrechner verwenden. Führt das ausgewählte installierte Szenario oder alle Szenarien des Rezepts aus, versucht die Wiederherstellung und schreibt Aufzeichnungen und Artefakte unter OUTPUT_DIR. Textausgabe; 3 bei mindestens einem fehlgeschlagenen Szenario, 0 wenn keines fehlschlug (blockierte Szenarien sind weiterhin möglich), 2 bei verweigerten Schutzprüfungen oder ungültiger Eingabe, 130 bei Abbruch. Prüfen Sie jedes Ergebnis und Wiederherstellungsprotokoll; Code 0 allein ist keine Validierungsfreigabe.",
    "cli_ref_forms": "Weitere akzeptierte Optionen und Workflow-Formen",
    "cli_ref_forms_intro": "Die nach Kategorien geordnete Referenz unten deckt alle öffentlichen Befehle ab. Die erweiterten Formen enthalten Optionen, die in den kürzeren Einträgen leicht übersehen werden.",
    "cli_ref_bitlocker_form": "<code>bitlocker-plan [--volume C:] [--operation Inspect|BackupRecovery|Encrypt|ResumeProtection] [--encryption Aes128|Aes256|XtsAes128|XtsAes256] [--used-space-only] [--backup File|ActiveDirectory|EntraId] [--backup-file PATH] [--inspect]</code>: Nur Planung als Text. <code>--inspect</code> liest das gewählte Volume; keine Änderung von Schutzeinstellungen. Für tatsächliche Operationen den dafür vorgesehenen abgesicherten Befehl verwenden.",
    "cli_ref_debloat_form": "<code>debloat-review --area AREA [--area AREA ...] [--all-profiles] [--keep-office-culture CULTURE] [--sleep-ac MINUTES --sleep-dc MINUTES --display-ac MINUTES --display-dc MINUTES] [--apply-high-performance|--apply-power-timers|--disable-hibernation] [--json]</code>: Standardmäßig Prüfung. Jeder ausdrückliche Energieschalter nimmt ohne zusätzliches <code>--execute</code> eine Änderung vor. Wählen Sie genau einen Ausführungsschalter und nur den zugehörigen Bereich: HighPerformancePower, SleepAndDisplayTimers oder Hibernation. Alle vier Timerwerte sind gemeinsam erforderlich, jeweils 0 bis 1440 Minuten; null bedeutet Nie. Ausstehende Energieeinträge werden abgeglichen, statt die Änderung zu wiederholen. Standardmäßig Text, mit <code>--json</code> JSON; blockierte oder ungeprüfte Nachweise bleiben ausdrücklich gekennzeichnet.",
    "cli_ref_depot_form": "<code>depot-review [--microsoft-365] [--onedrive] [--teams] [--chrome] [--acrobat-reader] [--zoom] [--7zip] [--windows-updates] [--computer-name] [--local-admin] [--admin-review] [--browser-extensions] [--cleanup] [--edge] [--privacy] [--taskbar] [--start-menu] [--notifications] [--json]</code>: Mindestens eine Anwendungs- oder Konfigurationsgruppe wählen. Nur Einrichtungsprüfung als Text oder JSON; kein Installationsdownload, keine Kontoerstellung oder Konfigurationsänderung.",
    "cli_ref_audio_form": "<code>device-check audio [--knowledge PACK_PATH ...] [--direction output|input] [--role console|multimedia|communications]</code>: Optionale Richtungs- und Rollenfilter gelten nur für Audio. <code>--knowledge PATH</code> für jedes der höchstens 32 Pakete wiederholen. Schreibgeschütztes JSON; keiner der Filter ändert den Standardaudioendpunkt.",
    "cli_ref_privacy_form": "<code>privacy-plan [--select AREA ...] [--inspect]</code>: Textvorschau oder schreibgeschützte Registrierungsprüfung. Alle sechs action-, recover- und undo-Formen von <code>privacy-setting</code> und <code>privacy-clipboard-history</code> akzeptieren auch <code>--journal-folder PATH</code>. Verwenden Sie für Ausführung und Wiederherstellung denselben Ordner. Aktionen und Rücknahmen zeigen ohne <code>--execute</code> nur eine Vorschau; die Wiederherstellung wiederholt die Änderung nie.",
    "cli_ref_update_search_form": "<code>update-search [--source Configured|WindowsUpdate|MicrosoftUpdate] [--drivers] [--no-software] [--filter TITLE] [--downloaded-only] [--classification GUID] [--product GUID]</code>: Schreibgeschützte Suche mit JSON-Ausgabe und exakt passenden Identitäten. Die Quellenauswahl erlaubt weder Download noch Installation.",
    "cli_ref_update_plan_form": "<code>update-plan --select GUID:REVISION [--select GUID:REVISION ...] [--source Configured|WindowsUpdate|MicrosoftUpdate] [--drivers] [--no-software] [--allow-restart-required] [--allow-feature-upgrade] [--json] [--execute]</code>: Vor der Vorschau erfolgt eine erneute Suche. Funktionsupgrades benötigen beide Freigabeflags und müssen allein ausgewählt werden. Die Installation erfordert <code>--execute</code> und durch Schutzprüfungen bestätigte Eignung. <code>update-recover</code> akzeptiert keine Optionen und installiert niemals Updates.",
    "cli_ref_workflow_form": "<code>workflow WORKFLOW [--recipes ID[,ID]] [--auto-repair] [--report OUTPUT.html|OUTPUT.txt] [--json]</code>: Gültige Namen mit <code>workflows</code>, erlaubte Rezept-IDs mit <code>recipes WORKFLOW</code> ermitteln. Schreibgeschützt, sofern der jeweilige gezielte Workflow <code>--auto-repair</code> nicht unterstützt und erhält; jede Reparatur erfordert weiterhin Eignung und Überprüfung. Common-problems/full-scan lehnt automatische Reparaturen ab. <code>--set KEY=VALUE</code>-Pläne bleiben schreibgeschützt und lassen sich nicht mit Rezeptauswahl, Umfangsauswahl oder automatischer Reparatur kombinieren. Der .html- oder .txt-Pfad eines Berichts darf noch nicht existieren.",
    "cli_ref_workflow_scopes": "<code>workflow background-transfers [--all-users] [--json]</code>: Begrenzte Transferprüfung ohne automatische Reparatur. Installed-apps akzeptiert <code>--current-user</code>; app-packages akzeptiert <code>--all-users</code> und <code>--include-provisioned</code>. Defender akzeptiert <code>--skip-tpm</code>, <code>--skip-secure-boot</code> und <code>--skip-virtualization</code>. Der Workflow available-updates akzeptiert <code>--source Configured|WindowsUpdate|MicrosoftUpdate</code>, <code>--drivers</code> und <code>--no-software</code>; seine Option <code>--third-party</code> ist in dieser Version deaktiviert.",
    "cli_ref_exit_limits": "Rückgabecodes zusammen mit dem Befehlsergebnis auswerten: Erfolgreiches Kataloglesen, historischer Import, Planexport oder Analyse beurteilen nicht den Rechnerzustand. Code 5 von symptom bedeutet, dass die Behebung des ursprünglichen Problems unbestätigt bleibt. Native Validierung kann bei blockierten Szenarien 0 liefern. Unvollständige Nachweise bleiben unvollständig. <code>recover</code>-Befehle gleichen die aufgezeichnete Operation ab und erlauben keinen erneuten Versuch.",
    "cli_ref_full_link": "Alle Befehle, akzeptierte Syntax, Ausgaben, Grenzen und Ausführungsbedingungen finden Sie in der <a href=\"../help.html#cli\">vollständigen Befehlszeilenreferenz auf der Hilfeseite</a>. Diese Seite stellt die wichtigsten Workflows vor."
  },
  "es": {
    "cli_ref_discovery": "Descubrimiento de comandos, evaluación inicial y pruebas locales",
    "cli_ref_conventions": "Antepon a cada comando <code>killerbench-cli</code>. Pon entre comillas las rutas o el texto con espacios. Los corchetes indican argumentos opcionales; la barra vertical separa alternativas. Si aparece <code>...</code>, repite la opción completa. Las opciones pertenecen al comando indicado, no a todos. Usa <code>capabilities</code> para obtener la lista de nombres legible por máquinas, incluidos los reservados para versiones posteriores. Para la ayuda de consola, usa <code>help</code>, <code>--help</code>, <code>-h</code> o ningún argumento.",
    "cli_ref_exceptions": "La regla general de vista previa tiene excepciones: <code>symptom run --repair</code>, <code>workflow --auto-repair</code> y los tres modificadores de energía de <code>debloat-review</code> autorizan sus cambios documentados sin <code>--execute</code>. <code>validate-native</code> solo introduce fallos en un entorno desechable protegido. La exportación de paquetes, los planes guardados, los diarios y los informes también escriben archivos locales. JSON solo está disponible donde se indica; el descubrimiento y la validación de paquetes, el análisis de texto sin formato y varias vistas previas usan texto. Los avisos de progreso y capacidades pueden aparecer en la salida de error estándar aunque el comando termine correctamente.",
    "cli_ref_profile_backup_limits": "<code>profiles --backup-to</code> admite entradas de perfil sin cifrar. Rechaza los orígenes cifrados con EFS antes de crear el destino de la copia.",
    "cli_ref_capabilities": "<code>capabilities [--json]</code>: Devuelve JSON en ambas formas: <code>schemaVersion</code> (1), <code>version</code> del ensamblado y <code>commands</code> únicos y ordenados (cadenas). Sin diagnósticos ni reparaciones. Solo admite la opción <code>--json</code>; código 0 si tiene éxito, 2 para otros argumentos. Que un nombre aparezca no demuestra compatibilidad nativa ni disponibilidad en la versión.",
    "cli_ref_pack": "<code>pack list | pack export PACK_ID OUTPUT.json | pack validate PACK.json</code>: Enumera paquetes integrados, etiquetas de capacidades de recetas y primitivas; exporta un paquete integrado a una ruta de salida que no exista; o valida un paquete local con la biblioteca de primitivas de Windows. Salida de texto; no ejecuta recetas. La exportación crea directorios superiores. Códigos: 0 éxito, 2 argumentos no válidos, ID desconocidos o salida existente, 3 paquetes no válidos o ilegibles.",
    "cli_ref_symptom": "<code>symptom list | symptom search TEXT | symptom run SYMPTOM_ID [--repair] [--explicit] [--option NAME=VALUE]... [--answer NODE=KEY]... [--json]</code>: Enumera o busca ID de síntomas compatibles y recorre un árbol de evaluación limitado. Por defecto solo detecta. <code>--repair</code> autoriza recetas automáticas de paquetes con comprobaciones nuevas; <code>--explicit</code> confirma además las recetas que exigen opciones explícitas y requiere <code>--repair</code>. Cada receta se aplica una vez como máximo; límites predeterminados: 40 pasos, 10 reparaciones y 30 minutos. Las preguntas sin responder quedan abiertas. Escribe un diario local Triage y devuelve texto o JSON. Códigos: 0 resuelto o descartado, 3 sin resolver o bloqueado, 4 requiere reinicio, 5 reparación de componente verificada sin confirmar que haya desaparecido el síntoma, 130 cancelado. Una búsqueda sin coincidencias devuelve 3; entrada no válida, 2.",
    "cli_ref_investigate": "<code>investigate FILE_PATH [--json]</code>: Aplica reglas de pruebas compatibles a un registro de texto local, archivo EVTX guardado o documento XML exportado de eventos de Windows, con explicaciones, referencias y siguientes pasos. El texto importado lee hasta 1,000,000 caracteres y 10,000 entradas analizadas. EVTX requiere Windows y conserva los 200 registros más recientes; XML conserva los primeros 200 en orden de archivo. Ninguna importación de eventos filtra por fecha; las pruebas históricas no establecen el estado actual del equipo. El análisis tiene un plazo de cancelación de 15 segundos. Texto por defecto, JSON con <code>--json</code>. Códigos: 0 análisis completo, 3 pruebas parciales, 1 entrada ilegible o no compatible, 2 argumentos no válidos, 130 cancelación o tiempo agotado. No repara.",
    "cli_ref_analyze": "<code>analyze TEXT_LOG_PATH [--json]</code>: Extrae observaciones de códigos distintos de un registro de texto sin diagnosticar causas ni realizar cambios. Lee hasta 1,000,000 caracteres, conserva hasta 256 códigos y ocho referencias por código; plazo de cancelación de 15 segundos. Texto por defecto o JSON con <code>--json</code>. Códigos: 0 análisis completo, 3 truncamiento, 1 error de entrada, 2 argumentos no válidos, 130 cancelación o tiempo agotado.",
    "cli_ref_duplicate_files": "<code>duplicate-files FOLDER [--min-bytes N] [--max-files N] [--report]</code>: Revisión de duplicados SHA-256 de una carpeta local, de solo lectura. Valores predeterminados: mínimo un byte, 10,000 archivos; el mínimo admite cero y el límite de archivos de 1 a 100,000. El cálculo de hashes se limita a 100 GiB en total. JSON por defecto o texto con <code>--report</code>; ambas salidas pueden revelar rutas. No selecciona archivos para eliminar. Códigos: 0 completo, 3 incompleto, 1 error de análisis/entrada, 2 opciones mal formadas, 130 cancelado.",
    "cli_ref_large_files": "<code>large-files FOLDER [--min-bytes N] [--max-files N] [--limit N] [--report]</code>: Revisión de tamaños de una carpeta local, de solo lectura. Valores predeterminados: mínimo 100 MiB, 10,000 archivos examinados y 500 resultados conservados. El mínimo debe ser positivo; límite de archivos de 1 a 100,000 y de resultados de 1 a 10,000. JSON por defecto o texto con <code>--report</code>; incluye rutas. Códigos: 0 completo, 3 incompleto, 1 error de análisis/entrada, 2 opciones mal formadas, 130 cancelado. No limpia archivos.",
    "cli_ref_file_limits": "Ambas revisiones omiten puntos de reanálisis y limitan el recorrido: por defecto, 10,000 directorios, 1,024 directorios pendientes, profundidad 128 y 30 segundos. El contenido inaccesible o cualquier límite alcanzado de recorrido, hashes, archivos o resultados deja la revisión incompleta. Son límites de cobertura, no pruebas de que los archivos omitidos sean seguros.",
    "cli_ref_debloat_recover": "<code>debloat-recover power-plan|power-timers|hibernation --folder PATH [--json]</code>: Concilia un tipo de operación de energía pendiente mediante la ruta absoluta de su carpeta de diario. Selecciona la misma carpeta que contiene el registro pendiente, normalmente <code>%LOCALAPPDATA%\\KillerBench\\Debloat</code>. Siempre devuelve JSON, con o sin <code>--json</code>; el progreso va a la salida de error estándar. No repite cambios de energía. Puede archivar registros locales resueltos. Códigos: 0 ningún registro pendiente o estado verificado, 3 pruebas sin resolver, 1 error de archivo/proveedor, 2 argumentos no válidos o ruta relativa/ausente de carpeta, 130 cancelado. Sin opción <code>--execute</code>.",
    "cli_ref_gated": "Restricciones de versión y validación nativa en entornos desechables",
    "cli_ref_third_party_updates": "<code>third-party-updates</code>: Descubrimiento reservado de actualizaciones de aplicaciones con Microsoft.WinGet.Client, de solo lectura. Desactivado en esta versión; devuelve 2 y el aviso de disponibilidad de KillerBench 1.1 sin realizar el descubrimiento. Al activarse, genera JSON; 0 descubrimiento completo y disponible, 3 incompleto o no disponible, 1 error del proveedor, 130 cancelación.",
    "cli_ref_third_party_update": "<code>third-party-update ID SOURCE VERSION [--accept-agreements] [--execute]</code>: Actualización reservada de un paquete exacto; actualmente desactivada con código 2. Al activarse, muestra por defecto una vista previa del ID, origen y versión exactos recién descubiertos. Ejecutarla requiere ambos modificadores tras revisar la selección, repite las medidas de protección y registra la solicitud. Salida JSON; la elegibilidad y los resultados de ejecución quedan explícitos. Rechaza indicadores repetidos o desconocidos. Sin actualización masiva ni aceptación implícita de acuerdos.",
    "cli_ref_third_party_recover": "<code>third-party-update-recover</code>: Conciliación reservada de una versión exacta pendiente; actualmente desactivada con código 2. Al activarse, lee el diario local ThirdPartyUpdates y verifica el estado sin reintentar la instalación. Salida JSON; 0 ningún registro pendiente o estado verificado, 3 pruebas sin resolver, 130 cancelación. No admite opciones.",
    "cli_ref_validate_native": "<code>validate-native RECIPE_ID SCENARIO_SUFFIX|all OUTPUT_DIR --disposable MACHINE_NAME</code>: Validación mediante inyección de fallos, no diagnóstico de solo lectura ni vista previa. Requiere acceso de administrador, el nombre exacto del equipo y <code>KILLERBENCH_DISPOSABLE=yes-this-machine-is-disposable</code> en un equipo Windows desechable. Nunca uses un equipo de desarrollo o de un cliente. Ejecuta el escenario instalado seleccionado o todos los de la receta, intenta restaurar el estado y escribe registros y artefactos en OUTPUT_DIR. Salida de texto; 3 si falla algún escenario, 0 si no falla ninguno (aún puede haber escenarios bloqueados), 2 si las protecciones rechazan la ejecución o la entrada no es válida, 130 por cancelación. Revisa cada resultado y registro de restauración; el código 0 por sí solo no acredita la validación.",
    "cli_ref_forms": "Opciones y formas de flujo de trabajo adicionales admitidas",
    "cli_ref_forms_intro": "La referencia por categorías de abajo cubre todos los comandos públicos. Estas formas ampliadas incluyen opciones fáciles de pasar por alto en las entradas breves.",
    "cli_ref_bitlocker_form": "<code>bitlocker-plan [--volume C:] [--operation Inspect|BackupRecovery|Encrypt|ResumeProtection] [--encryption Aes128|Aes256|XtsAes128|XtsAes256] [--used-space-only] [--backup File|ActiveDirectory|EntraId] [--backup-file PATH] [--inspect]</code>: Solo planificación en texto. <code>--inspect</code> lee el volumen seleccionado sin cambiar la protección. Para una operación real, usa el comando protegido específico.",
    "cli_ref_debloat_form": "<code>debloat-review --area AREA [--area AREA ...] [--all-profiles] [--keep-office-culture CULTURE] [--sleep-ac MINUTES --sleep-dc MINUTES --display-ac MINUTES --display-dc MINUTES] [--apply-high-performance|--apply-power-timers|--disable-hibernation] [--json]</code>: Revisión por defecto. Cada modificador explícito de energía realiza un cambio sin añadir <code>--execute</code>. Selecciona exactamente un modificador de ejecución y solo su área correspondiente: HighPerformancePower, SleepAndDisplayTimers o Hibernation. Los cuatro temporizadores deben indicarse juntos, cada uno de 0 a 1440 minutos; cero significa Nunca. Concilia los registros de energía pendientes en vez de repetir el cambio. Texto por defecto o JSON con <code>--json</code>; las pruebas bloqueadas o no verificadas quedan explícitas.",
    "cli_ref_depot_form": "<code>depot-review [--microsoft-365] [--onedrive] [--teams] [--chrome] [--acrobat-reader] [--zoom] [--7zip] [--windows-updates] [--computer-name] [--local-admin] [--admin-review] [--browser-extensions] [--cleanup] [--edge] [--privacy] [--taskbar] [--start-menu] [--notifications] [--json]</code>: Selecciona al menos una aplicación o grupo de configuración. Solo revisión de preparación en texto o JSON; sin descargar instaladores, crear cuentas ni cambiar configuraciones.",
    "cli_ref_audio_form": "<code>device-check audio [--knowledge PACK_PATH ...] [--direction output|input] [--role console|multimedia|communications]</code>: Los filtros opcionales de dirección y función solo se aplican al audio. Repite <code>--knowledge PATH</code> por cada paquete, hasta 32. JSON de solo lectura; ningún filtro cambia el punto de conexión de audio predeterminado.",
    "cli_ref_privacy_form": "<code>privacy-plan [--select AREA ...] [--inspect]</code>: Vista previa en texto o inspección del registro de solo lectura. Las seis formas action, recover y undo de <code>privacy-setting</code> y <code>privacy-clipboard-history</code> también admiten <code>--journal-folder PATH</code>. Usa la misma carpeta para ejecución y recuperación. Las acciones y deshacer solo muestran una vista previa salvo que se indique <code>--execute</code>; la recuperación nunca repite el cambio.",
    "cli_ref_update_search_form": "<code>update-search [--source Configured|WindowsUpdate|MicrosoftUpdate] [--drivers] [--no-software] [--filter TITLE] [--downloaded-only] [--classification GUID] [--product GUID]</code>: Descubrimiento de solo lectura con JSON e identidades de coincidencia exacta. Seleccionar el origen no autoriza descargar ni instalar.",
    "cli_ref_update_plan_form": "<code>update-plan --select GUID:REVISION [--select GUID:REVISION ...] [--source Configured|WindowsUpdate|MicrosoftUpdate] [--drivers] [--no-software] [--allow-restart-required] [--allow-feature-upgrade] [--json] [--execute]</code>: La vista previa va precedida de un descubrimiento nuevo. Las actualizaciones de características requieren ambos indicadores de permiso y deben seleccionarse solas. Instalar requiere <code>--execute</code> y elegibilidad confirmada por las protecciones. <code>update-recover</code> no admite opciones ni instala actualizaciones.",
    "cli_ref_workflow_form": "<code>workflow WORKFLOW [--recipes ID[,ID]] [--auto-repair] [--report OUTPUT.html|OUTPUT.txt] [--json]</code>: Usa <code>workflows</code> para nombres válidos y <code>recipes WORKFLOW</code> para ID de recetas permitidas. Solo lectura salvo que el flujo específico admita y reciba <code>--auto-repair</code>; cada reparación sigue requiriendo elegibilidad y verificación. Common-problems/full-scan rechaza la reparación automática. Los planes <code>--set KEY=VALUE</code> son de solo lectura y no pueden combinarse con selección de recetas, selección de ámbito o reparación automática. El informe exige una ruta .html o .txt que aún no exista.",
    "cli_ref_workflow_scopes": "<code>workflow background-transfers [--all-users] [--json]</code>: Inspección limitada de transferencias sin reparación automática. Installed-apps admite <code>--current-user</code>; app-packages admite <code>--all-users</code> y <code>--include-provisioned</code>. Defender admite <code>--skip-tpm</code>, <code>--skip-secure-boot</code> y <code>--skip-virtualization</code>. El flujo available-updates admite <code>--source Configured|WindowsUpdate|MicrosoftUpdate</code>, <code>--drivers</code> y <code>--no-software</code>; su opción <code>--third-party</code> está desactivada en esta versión.",
    "cli_ref_exit_limits": "Interpreta los códigos junto con el resultado de cada comando: leer un catálogo, importar datos históricos, exportar un plan o analizar correctamente no es un dictamen de salud del equipo. El código 5 de symptom indica que la resolución del problema original sigue sin confirmar. La validación nativa puede devolver 0 con escenarios bloqueados. Las pruebas incompletas deben seguir considerándose incompletas. Los comandos <code>recover</code> concilian la operación registrada sin autorizar su reintento.",
    "cli_ref_full_link": "Consulta todos los comandos, sintaxis admitidas, salidas, límites y condiciones de ejecución en la <a href=\"../help.html#cli\">referencia completa de la línea de comandos de la página de ayuda</a>. Esta página presenta los flujos principales."
  },
  "fr": {
    "cli_ref_discovery": "Découverte des commandes, triage et éléments de preuve locaux",
    "cli_ref_conventions": "Faites précéder chaque commande ci-dessous de <code>killerbench-cli</code>. Placez les chemins ou textes contenant des espaces entre guillemets. Les crochets indiquent des arguments facultatifs; la barre verticale sépare les alternatives. Avec <code>...</code>, répétez l'option entière. Les options concernent uniquement la commande indiquée. Utilisez <code>capabilities</code> pour la liste des noms lisible par machine, y compris ceux réservés à de futures versions; utilisez <code>help</code>, <code>--help</code>, <code>-h</code> ou aucun argument pour l'aide en console.",
    "cli_ref_exceptions": "La règle générale d'aperçu comporte des exceptions: <code>symptom run --repair</code>, <code>workflow --auto-repair</code> et les trois options d'alimentation de <code>debloat-review</code> autorisent les modifications documentées sans <code>--execute</code>. <code>validate-native</code> n'injecte des pannes que dans un environnement jetable protégé. Les exports de packs, plans enregistrés, journaux et rapports écrivent aussi des fichiers locaux. JSON n'est disponible que lorsque cela est indiqué; la découverte et la validation de packs, l'analyse de texte brut et plusieurs aperçus utilisent du texte. Les avis de progression et de capacités peuvent apparaître sur la sortie d'erreur standard même en cas de réussite.",
    "cli_ref_profile_backup_limits": "<code>profiles --backup-to</code> prend en charge les entrées de profil non chiffrées. Une source chiffrée avec EFS est refusée avant la création de la destination de sauvegarde.",
    "cli_ref_capabilities": "<code>capabilities [--json]</code>: Renvoie du JSON dans les deux formes: <code>schemaVersion</code> (1), <code>version</code> de l'assembly et <code>commands</code> triés et uniques (chaînes). Aucun diagnostic ni réparation. Accepte seulement l'option <code>--json</code>; code 0 en cas de réussite, 2 pour les autres arguments. Un nom présent ne prouve ni la prise en charge native ni la disponibilité dans la version.",
    "cli_ref_pack": "<code>pack list | pack export PACK_ID OUTPUT.json | pack validate PACK.json</code>: Liste les packs intégrés, les libellés de capacités des recettes et les primitives; exporte un pack intégré vers un chemin de sortie inexistant; ou valide un pack local avec la bibliothèque de primitives Windows. Sortie texte, aucune recette exécutée. L'export crée les répertoires parents. Codes: 0 réussite, 2 arguments invalides, ID inconnus ou sortie existante, 3 packs invalides ou illisibles.",
    "cli_ref_symptom": "<code>symptom list | symptom search TEXT | symptom run SYMPTOM_ID [--repair] [--explicit] [--option NAME=VALUE]... [--answer NODE=KEY]... [--json]</code>: Liste ou recherche les ID de symptômes pris en charge, puis parcourt un arbre de triage borné. Par défaut, le lancement détecte seulement. <code>--repair</code> autorise les recettes automatiques des packs avec de nouvelles vérifications; <code>--explicit</code> confirme aussi les recettes exigeant des options explicites et nécessite <code>--repair</code>. Chaque recette s'applique au plus une fois; limites par défaut: 40 étapes, 10 réparations et 30 minutes. Les questions sans réponse restent ouvertes. Écrit un journal local Triage et renvoie du texte ou du JSON. Codes: 0 résolu ou écarté, 3 non résolu ou bloqué, 4 redémarrage nécessaire, 5 réparation du composant vérifiée sans confirmation de disparition du symptôme, 130 annulé. Recherche sans résultat: 3; entrée invalide: 2.",
    "cli_ref_investigate": "<code>investigate FILE_PATH [--json]</code>: Applique les règles d'analyse de preuves prises en charge à un journal texte local, une archive EVTX enregistrée ou un document XML d'événements Windows exporté, avec explications, références et étapes suivantes. L'import texte lit au plus 1,000,000 caractères et 10,000 entrées analysées. EVTX nécessite Windows et conserve les 200 enregistrements les plus récents; XML conserve les 200 premiers dans l'ordre du fichier. Aucun des imports d'événements ne filtre par date; les preuves historiques n'établissent pas l'état actuel de la machine. L'analyse a un délai d'annulation de 15 secondes. Texte par défaut, JSON avec <code>--json</code>. Codes: 0 analyse terminée, 3 preuves partielles, 1 entrée illisible ou non prise en charge, 2 arguments invalides, 130 annulation ou délai dépassé. Aucune réparation.",
    "cli_ref_analyze": "<code>analyze TEXT_LOG_PATH [--json]</code>: Extrait les observations de codes distincts d'un journal texte sans diagnostiquer de cause ni effectuer de modification. Lit au plus 1,000,000 caractères, conserve au plus 256 codes et huit références par code; délai d'annulation de 15 secondes. Texte par défaut ou JSON avec <code>--json</code>. Codes: 0 analyse complète, 3 troncature, 1 erreur d'entrée, 2 arguments invalides, 130 annulation ou délai dépassé.",
    "cli_ref_duplicate_files": "<code>duplicate-files FOLDER [--min-bytes N] [--max-files N] [--report]</code>: Recherche de doublons SHA-256 en lecture seule dans un dossier local. Valeurs par défaut: minimum un octet, 10,000 fichiers; le minimum accepte zéro, la limite de fichiers va de 1 à 100,000. Le hachage est limité à 100 GiB au total. JSON par défaut ou texte avec <code>--report</code>; les deux peuvent révéler les chemins. Aucun fichier sélectionné pour suppression. Codes: 0 complet, 3 incomplet, 1 erreur d'analyse/d'entrée, 2 options mal formées, 130 annulé.",
    "cli_ref_large_files": "<code>large-files FOLDER [--min-bytes N] [--max-files N] [--limit N] [--report]</code>: Examen des tailles en lecture seule dans un dossier local. Valeurs par défaut: minimum 100 MiB, 10,000 fichiers examinés et 500 résultats conservés. Minimum strictement positif; limite de fichiers de 1 à 100,000 et de résultats de 1 à 10,000. JSON par défaut ou texte avec <code>--report</code>; la sortie contient les chemins. Codes: 0 complet, 3 incomplet, 1 erreur d'analyse/d'entrée, 2 options mal formées, 130 annulé. Aucun nettoyage.",
    "cli_ref_file_limits": "Les deux examens ignorent les points d'analyse (reparse points) et bornent le parcours: par défaut 10,000 répertoires, 1,024 répertoires en attente, profondeur 128 et 30 secondes. Tout contenu inaccessible ou toute limite de parcours, hachage, fichiers ou résultats atteinte laisse l'examen incomplet. Ce sont des limites de couverture, pas une preuve de sécurité des fichiers omis.",
    "cli_ref_debloat_recover": "<code>debloat-recover power-plan|power-timers|hibernation --folder PATH [--json]</code>: Rapproche l'état d'un type d'opération d'alimentation en attente à partir du chemin absolu de son dossier de journal. Choisissez le même dossier contenant l'enregistrement en attente, normalement <code>%LOCALAPPDATA%\\KillerBench\\Debloat</code>. Renvoie toujours du JSON, avec ou sans <code>--json</code>; la progression va sur la sortie d'erreur standard. Ne répète pas la modification d'alimentation. Les enregistrements locaux résolus peuvent être archivés. Codes: 0 aucun enregistrement en attente ou état vérifié, 3 preuves non résolues, 1 erreur de fichier/fournisseur, 2 arguments invalides ou chemin de dossier relatif/absent, 130 annulé. Pas d'option <code>--execute</code>.",
    "cli_ref_gated": "Restrictions de version et validation native en environnement jetable",
    "cli_ref_third_party_updates": "<code>third-party-updates</code>: Découverte réservée des mises à jour d'applications via Microsoft.WinGet.Client, en lecture seule. Désactivée dans cette version; renvoie 2 avec l'avis de disponibilité de KillerBench 1.1 sans recherche. Une fois activée, produit du JSON; 0 découverte complète et disponible, 3 incomplète ou indisponible, 1 échec du fournisseur, 130 annulation.",
    "cli_ref_third_party_update": "<code>third-party-update ID SOURCE VERSION [--accept-agreements] [--execute]</code>: Mise à jour réservée d'un package exact; actuellement désactivée avec le code 2. Une fois activée, affiche par défaut l'aperçu de l'ID, de la source et de la version exacts nouvellement découverts. Après examen de la sélection, l'exécution exige les deux options, répète les protections et journalise la demande. Sortie JSON; l'admissibilité et les résultats d'exécution restent explicites. Options en double ou inconnues refusées. Aucune mise à niveau globale ni acceptation implicite des accords.",
    "cli_ref_third_party_recover": "<code>third-party-update-recover</code>: Rapprochement réservé d'une version exacte en attente; actuellement désactivé avec le code 2. Une fois activé, lit le journal local ThirdPartyUpdates et vérifie l'état sans retenter l'installation. Sortie JSON; 0 aucun enregistrement en attente ou état vérifié, 3 preuves non résolues, 130 annulation. Aucune option acceptée.",
    "cli_ref_validate_native": "<code>validate-native RECIPE_ID SCENARIO_SUFFIX|all OUTPUT_DIR --disposable MACHINE_NAME</code>: Validation par injection de pannes, pas un diagnostic en lecture seule ni un aperçu. Nécessite les droits administrateur, le nom exact de la machine et <code>KILLERBENCH_DISPOSABLE=yes-this-machine-is-disposable</code> sur une machine Windows jetable. N'utilisez jamais une machine de développement ou de client. Exécute le scénario installé sélectionné ou tous ceux de la recette, tente la restauration et écrit les enregistrements et artefacts sous OUTPUT_DIR. Sortie texte; 3 si un scénario échoue, 0 si aucun n'échoue (des scénarios bloqués peuvent subsister), 2 si les protections refusent ou si l'entrée est invalide, 130 en cas d'annulation. Examinez chaque résultat et chaque trace de restauration; le seul code 0 ne vaut pas validation.",
    "cli_ref_forms": "Options et formes de workflow supplémentaires acceptées",
    "cli_ref_forms_intro": "La référence classée ci-dessous couvre toutes les commandes publiques. Ces formes développées conservent les options faciles à manquer dans les entrées courtes.",
    "cli_ref_bitlocker_form": "<code>bitlocker-plan [--volume C:] [--operation Inspect|BackupRecovery|Encrypt|ResumeProtection] [--encryption Aes128|Aes256|XtsAes128|XtsAes256] [--used-space-only] [--backup File|ActiveDirectory|EntraId] [--backup-file PATH] [--inspect]</code>: Planification texte uniquement. <code>--inspect</code> lit le volume sélectionné sans modifier la protection. Utilisez la commande protégée dédiée pour une opération réelle.",
    "cli_ref_debloat_form": "<code>debloat-review --area AREA [--area AREA ...] [--all-profiles] [--keep-office-culture CULTURE] [--sleep-ac MINUTES --sleep-dc MINUTES --display-ac MINUTES --display-dc MINUTES] [--apply-high-performance|--apply-power-timers|--disable-hibernation] [--json]</code>: Examen par défaut. Chaque option explicite d'alimentation effectue une modification sans ajouter <code>--execute</code>. Sélectionnez exactement une option d'exécution et uniquement sa zone correspondante: HighPerformancePower, SleepAndDisplayTimers ou Hibernation. Les quatre valeurs de minuterie sont requises ensemble, chacune de 0 à 1440 minutes; zéro signifie Jamais. Les enregistrements d'alimentation en attente sont rapprochés au lieu de répéter la modification. Texte par défaut ou JSON avec <code>--json</code>; les preuves bloquées ou non vérifiées restent explicites.",
    "cli_ref_depot_form": "<code>depot-review [--microsoft-365] [--onedrive] [--teams] [--chrome] [--acrobat-reader] [--zoom] [--7zip] [--windows-updates] [--computer-name] [--local-admin] [--admin-review] [--browser-extensions] [--cleanup] [--edge] [--privacy] [--taskbar] [--start-menu] [--notifications] [--json]</code>: Sélectionnez au moins une application ou un groupe de configuration. Examen de préparation en texte ou JSON uniquement; aucun téléchargement d'installateur, création de compte ou changement de configuration.",
    "cli_ref_audio_form": "<code>device-check audio [--knowledge PACK_PATH ...] [--direction output|input] [--role console|multimedia|communications]</code>: Les filtres facultatifs de direction et de rôle concernent uniquement l'audio. Répétez <code>--knowledge PATH</code> pour chacun des 32 packs au maximum. JSON en lecture seule; aucun filtre ne modifie le point de terminaison audio par défaut.",
    "cli_ref_privacy_form": "<code>privacy-plan [--select AREA ...] [--inspect]</code>: Aperçu texte ou inspection du registre en lecture seule. Les six formes action, recover et undo de <code>privacy-setting</code> et <code>privacy-clipboard-history</code> acceptent aussi <code>--journal-folder PATH</code>. Utilisez le même dossier pour l'exécution et la récupération. Les actions et annulations ne sont que des aperçus sans <code>--execute</code>; la récupération ne répète jamais la modification.",
    "cli_ref_update_search_form": "<code>update-search [--source Configured|WindowsUpdate|MicrosoftUpdate] [--drivers] [--no-software] [--filter TITLE] [--downloaded-only] [--classification GUID] [--product GUID]</code>: Découverte en lecture seule avec JSON et identités correspondant exactement. Choisir la source n'autorise ni téléchargement ni installation.",
    "cli_ref_update_plan_form": "<code>update-plan --select GUID:REVISION [--select GUID:REVISION ...] [--source Configured|WindowsUpdate|MicrosoftUpdate] [--drivers] [--no-software] [--allow-restart-required] [--allow-feature-upgrade] [--json] [--execute]</code>: Une nouvelle découverte précède l'aperçu. Les mises à niveau de fonctionnalités exigent les deux options d'autorisation et doivent être sélectionnées seules. L'installation exige <code>--execute</code> et l'admissibilité vérifiée par les protections. <code>update-recover</code> n'accepte aucune option et n'installe jamais de mises à jour.",
    "cli_ref_workflow_form": "<code>workflow WORKFLOW [--recipes ID[,ID]] [--auto-repair] [--report OUTPUT.html|OUTPUT.txt] [--json]</code>: Utilisez <code>workflows</code> pour les noms valides et <code>recipes WORKFLOW</code> pour les ID de recettes autorisés. Lecture seule sauf si le workflow ciblé prend en charge et reçoit <code>--auto-repair</code>; chaque réparation exige toujours admissibilité et vérification. Common-problems/full-scan refuse la réparation automatique. Les plans <code>--set KEY=VALUE</code> restent en lecture seule et ne se combinent pas avec la sélection de recettes, de portée ou la réparation automatique. Un rapport exige un chemin .html ou .txt inexistant.",
    "cli_ref_workflow_scopes": "<code>workflow background-transfers [--all-users] [--json]</code>: Inspection bornée des transferts, sans réparation automatique. Installed-apps accepte <code>--current-user</code>; app-packages accepte <code>--all-users</code> et <code>--include-provisioned</code>. Defender accepte <code>--skip-tpm</code>, <code>--skip-secure-boot</code> et <code>--skip-virtualization</code>. Le workflow available-updates accepte <code>--source Configured|WindowsUpdate|MicrosoftUpdate</code>, <code>--drivers</code> et <code>--no-software</code>; son option <code>--third-party</code> est désactivée dans cette version.",
    "cli_ref_exit_limits": "Interprétez les codes avec le résultat de chaque commande: la réussite d'une lecture de catalogue, d'un import historique, d'un export de plan ou d'une analyse n'est pas un verdict sur l'état de la machine. Le code 5 de symptom indique que la résolution du problème initial reste non confirmée. La validation native peut renvoyer 0 avec des scénarios bloqués. Les preuves incomplètes doivent rester incomplètes. Les commandes <code>recover</code> rapprochent l'opération enregistrée sans autoriser une nouvelle tentative.",
    "cli_ref_full_link": "Pour toutes les commandes, syntaxes acceptées, sorties, limites et conditions d'exécution, ouvrez la <a href=\"../help.html#cli\">référence complète de la ligne de commande sur la page d'aide</a>. Cette page présente les principaux workflows."
  },
  "it": {
    "cli_ref_discovery": "Individuazione dei comandi, valutazione iniziale e prove locali",
    "cli_ref_conventions": "Anteponi <code>killerbench-cli</code> a ogni comando seguente. Racchiudi tra virgolette percorsi o testo con spazi. Le parentesi quadre indicano argomenti facoltativi; la barra verticale separa le alternative. Con <code>...</code>, ripeti l'intera opzione. Le opzioni valgono solo per il comando indicato. Usa <code>capabilities</code> per l'elenco dei nomi leggibile dal computer, inclusi quelli riservati a versioni future; usa <code>help</code>, <code>--help</code>, <code>-h</code> o nessun argomento per la guida in console.",
    "cli_ref_exceptions": "La regola generale dell'anteprima ha eccezioni: <code>symptom run --repair</code>, <code>workflow --auto-repair</code> e le tre opzioni energetiche di <code>debloat-review</code> autorizzano le modifiche documentate senza <code>--execute</code>. <code>validate-native</code> introduce guasti solo in un ambiente protetto e sacrificabile. Anche esportazione dei pacchetti, piani salvati, registri e report scrivono file locali. JSON è disponibile solo dove indicato; individuazione e convalida dei pacchetti, analisi del testo semplice e varie anteprime usano testo. Gli avvisi su avanzamento e funzionalità possono apparire sul flusso di errore standard anche quando il comando riesce.",
    "cli_ref_profile_backup_limits": "<code>profiles --backup-to</code> supporta voci di profilo non crittografate. Una sorgente crittografata con EFS viene rifiutata prima di creare la destinazione del backup.",
    "cli_ref_capabilities": "<code>capabilities [--json]</code>: Restituisce JSON in entrambe le forme: <code>schemaVersion</code> (1), <code>version</code> dell'assembly e <code>commands</code> univoci e ordinati (stringhe). Nessuna diagnosi o riparazione. Accetta solo l'opzione <code>--json</code>; codice 0 se riesce, 2 per altri argomenti. Un nome elencato non dimostra supporto nativo né disponibilità nella versione.",
    "cli_ref_pack": "<code>pack list | pack export PACK_ID OUTPUT.json | pack validate PACK.json</code>: Elenca pacchetti integrati, etichette di capacità delle ricette e primitive; esporta un pacchetto integrato in un percorso di output inesistente; oppure convalida un pacchetto locale rispetto alla libreria di primitive Windows. Output testuale, nessuna ricetta eseguita. L'esportazione crea le directory superiori. Codici: 0 successo, 2 argomenti non validi, ID sconosciuti o output esistente, 3 pacchetti non validi o illeggibili.",
    "cli_ref_symptom": "<code>symptom list | symptom search TEXT | symptom run SYMPTOM_ID [--repair] [--explicit] [--option NAME=VALUE]... [--answer NODE=KEY]... [--json]</code>: Elenca o cerca ID di sintomi supportati, poi percorre un albero di valutazione limitato. Per impostazione predefinita rileva soltanto. <code>--repair</code> autorizza ricette automatiche dei pacchetti con nuovi controlli; <code>--explicit</code> conferma anche le ricette che richiedono opzioni esplicite e necessita di <code>--repair</code>. Ogni ricetta si applica al massimo una volta; limiti predefiniti: 40 passaggi, 10 riparazioni e 30 minuti. Le domande senza risposta restano aperte. Scrive un registro locale Triage e restituisce testo o JSON. Codici: 0 risolto o escluso, 3 irrisolto o bloccato, 4 riavvio necessario, 5 riparazione del componente verificata senza conferma della scomparsa del sintomo, 130 annullato. Ricerca senza risultati: 3; input non valido: 2.",
    "cli_ref_investigate": "<code>investigate FILE_PATH [--json]</code>: Applica le regole supportate per le prove a un registro testuale locale, un archivio EVTX salvato o un documento XML esportato degli eventi Windows, con spiegazioni, riferimenti e passi successivi. L'importazione testuale legge al massimo 1,000,000 caratteri e 10,000 voci analizzate. EVTX richiede Windows e conserva i 200 record più recenti; XML conserva i primi 200 nell'ordine del file. Nessuna importazione di eventi filtra per data; le prove storiche non stabiliscono lo stato attuale del computer. L'analisi ha un limite di annullamento di 15 secondi. Testo predefinito, JSON con <code>--json</code>. Codici: 0 analisi completata, 3 prove parziali, 1 input illeggibile o non supportato, 2 argomenti non validi, 130 annullamento o tempo scaduto. Nessuna riparazione.",
    "cli_ref_analyze": "<code>analyze TEXT_LOG_PATH [--json]</code>: Estrae osservazioni di codici distinti da un registro testuale senza diagnosticare cause né apportare modifiche. Legge al massimo 1,000,000 caratteri, conserva fino a 256 codici e otto riferimenti per codice; limite di annullamento di 15 secondi. Testo predefinito o JSON con <code>--json</code>. Codici: 0 analisi completa, 3 troncamento, 1 errore di input, 2 argomenti non validi, 130 annullamento o tempo scaduto.",
    "cli_ref_duplicate_files": "<code>duplicate-files FOLDER [--min-bytes N] [--max-files N] [--report]</code>: Verifica dei duplicati SHA-256 in una cartella locale, in sola lettura. Valori predefiniti: minimo un byte, 10,000 file; il minimo accetta zero, il limite dei file va da 1 a 100,000. Hashing limitato a 100 GiB complessivi. JSON predefinito o testo con <code>--report</code>; entrambi possono mostrare i percorsi. Nessun file viene selezionato per l'eliminazione. Codici: 0 completo, 3 incompleto, 1 errore scansione/input, 2 opzioni malformate, 130 annullato.",
    "cli_ref_large_files": "<code>large-files FOLDER [--min-bytes N] [--max-files N] [--limit N] [--report]</code>: Verifica delle dimensioni in una cartella locale, in sola lettura. Valori predefiniti: minimo 100 MiB, 10,000 file esaminati e 500 risultati conservati. Minimo positivo; limite dei file da 1 a 100,000 e dei risultati da 1 a 10,000. JSON predefinito o testo con <code>--report</code>; include i percorsi. Codici: 0 completo, 3 incompleto, 1 errore scansione/input, 2 opzioni malformate, 130 annullato. Nessuna pulizia.",
    "cli_ref_file_limits": "Entrambe le verifiche saltano i reparse point e limitano la visita: per impostazione predefinita 10,000 directory, 1,024 directory in attesa, profondità 128 e 30 secondi. Contenuti inaccessibili o qualsiasi limite raggiunto di visita, hashing, file o risultati lasciano la verifica incompleta. Sono limiti di copertura, non prove della sicurezza dei file omessi.",
    "cli_ref_debloat_recover": "<code>debloat-recover power-plan|power-timers|hibernation --folder PATH [--json]</code>: Riconcilia un tipo di operazione energetica in sospeso usando il percorso assoluto della cartella del registro. Seleziona la stessa cartella contenente il record in sospeso, normalmente <code>%LOCALAPPDATA%\\KillerBench\\Debloat</code>. Restituisce sempre JSON, con o senza <code>--json</code>; l'avanzamento va al flusso di errore standard. Non ripete modifiche energetiche. I record locali risolti possono essere archiviati. Codici: 0 nessun record in sospeso o stato verificato, 3 prove irrisolte, 1 errore file/provider, 2 argomenti non validi o percorso di cartella relativo/assente, 130 annullato. Nessuna opzione <code>--execute</code>.",
    "cli_ref_gated": "Restrizioni di versione e convalida nativa in ambienti sacrificabili",
    "cli_ref_third_party_updates": "<code>third-party-updates</code>: Individuazione riservata degli aggiornamenti delle applicazioni tramite Microsoft.WinGet.Client, in sola lettura. Disabilitata nella versione attuale; restituisce 2 con l'avviso di disponibilità di KillerBench 1.1 senza eseguire ricerche. Una volta attiva, produce JSON; 0 ricerca completa e disponibile, 3 incompleta o non disponibile, 1 errore del provider, 130 annullamento.",
    "cli_ref_third_party_update": "<code>third-party-update ID SOURCE VERSION [--accept-agreements] [--execute]</code>: Aggiornamento riservato di un pacchetto esatto; attualmente disabilitato con codice 2. Una volta attivo, mostra per impostazione predefinita l'anteprima di ID, origine e versione esatti appena rilevati. Dopo aver verificato la selezione, l'esecuzione richiede entrambe le opzioni, ripete le protezioni e registra la richiesta. Output JSON; idoneità ed esiti di esecuzione restano espliciti. Rifiuta opzioni duplicate o sconosciute. Nessun aggiornamento indiscriminato né accettazione implicita degli accordi.",
    "cli_ref_third_party_recover": "<code>third-party-update-recover</code>: Riconciliazione riservata di una versione esatta in sospeso; attualmente disabilitata con codice 2. Una volta attiva, legge il registro locale ThirdPartyUpdates e verifica lo stato senza ritentare l'installazione. Output JSON; 0 nessun record in sospeso o stato verificato, 3 prove irrisolte, 130 annullamento. Non accetta opzioni.",
    "cli_ref_validate_native": "<code>validate-native RECIPE_ID SCENARIO_SUFFIX|all OUTPUT_DIR --disposable MACHINE_NAME</code>: Convalida tramite iniezione di guasti, non diagnosi in sola lettura né anteprima. Richiede privilegi di amministratore, il nome esatto del computer e <code>KILLERBENCH_DISPOSABLE=yes-this-machine-is-disposable</code> su un computer Windows sacrificabile. Non usare mai un computer di sviluppo o di un cliente. Esegue lo scenario installato selezionato o tutti quelli della ricetta, tenta il ripristino e scrive record e artefatti in OUTPUT_DIR. Output testuale; 3 se fallisce uno scenario, 0 se nessuno fallisce (possono restare scenari bloccati), 2 se le protezioni rifiutano o l'input non è valido, 130 per annullamento. Esamina ogni esito e registro di ripristino; il solo codice 0 non certifica la convalida.",
    "cli_ref_forms": "Ulteriori opzioni e forme di flusso di lavoro accettate",
    "cli_ref_forms_intro": "La guida per categorie seguente copre ogni comando pubblico. Queste forme estese mantengono opzioni facili da perdere nelle voci brevi.",
    "cli_ref_bitlocker_form": "<code>bitlocker-plan [--volume C:] [--operation Inspect|BackupRecovery|Encrypt|ResumeProtection] [--encryption Aes128|Aes256|XtsAes128|XtsAes256] [--used-space-only] [--backup File|ActiveDirectory|EntraId] [--backup-file PATH] [--inspect]</code>: Solo pianificazione testuale. <code>--inspect</code> legge il volume selezionato senza modificare la protezione. Per operazioni reali usa il comando protetto dedicato.",
    "cli_ref_debloat_form": "<code>debloat-review --area AREA [--area AREA ...] [--all-profiles] [--keep-office-culture CULTURE] [--sleep-ac MINUTES --sleep-dc MINUTES --display-ac MINUTES --display-dc MINUTES] [--apply-high-performance|--apply-power-timers|--disable-hibernation] [--json]</code>: Verifica predefinita. Ogni opzione energetica esplicita apporta una modifica senza aggiungere <code>--execute</code>. Seleziona esattamente un'opzione di esecuzione e solo l'area corrispondente: HighPerformancePower, SleepAndDisplayTimers o Hibernation. Tutti e quattro i timer sono richiesti insieme, ciascuno da 0 a 1440 minuti; zero significa Mai. Riconcilia i record energetici in sospeso invece di ripetere la modifica. Testo predefinito o JSON con <code>--json</code>; le prove bloccate o non verificate restano esplicite.",
    "cli_ref_depot_form": "<code>depot-review [--microsoft-365] [--onedrive] [--teams] [--chrome] [--acrobat-reader] [--zoom] [--7zip] [--windows-updates] [--computer-name] [--local-admin] [--admin-review] [--browser-extensions] [--cleanup] [--edge] [--privacy] [--taskbar] [--start-menu] [--notifications] [--json]</code>: Seleziona almeno un'applicazione o gruppo di configurazione. Solo verifica della preparazione in testo o JSON; nessun download di programmi di installazione, creazione di account o cambio di configurazione.",
    "cli_ref_audio_form": "<code>device-check audio [--knowledge PACK_PATH ...] [--direction output|input] [--role console|multimedia|communications]</code>: I filtri facoltativi di direzione e ruolo valgono solo per l'audio. Ripeti <code>--knowledge PATH</code> per ciascun pacchetto, fino a 32. JSON in sola lettura; nessun filtro cambia l'endpoint audio predefinito.",
    "cli_ref_privacy_form": "<code>privacy-plan [--select AREA ...] [--inspect]</code>: Anteprima testuale o ispezione del registro in sola lettura. Tutte le sei forme action, recover e undo di <code>privacy-setting</code> e <code>privacy-clipboard-history</code> accettano anche <code>--journal-folder PATH</code>. Usa la stessa cartella per esecuzione e recupero. Azioni e annullamenti sono solo anteprime senza <code>--execute</code>; il recupero non ripete mai la modifica.",
    "cli_ref_update_search_form": "<code>update-search [--source Configured|WindowsUpdate|MicrosoftUpdate] [--drivers] [--no-software] [--filter TITLE] [--downloaded-only] [--classification GUID] [--product GUID]</code>: Individuazione in sola lettura con JSON e identità corrispondenti esattamente. La scelta dell'origine non autorizza download né installazioni.",
    "cli_ref_update_plan_form": "<code>update-plan --select GUID:REVISION [--select GUID:REVISION ...] [--source Configured|WindowsUpdate|MicrosoftUpdate] [--drivers] [--no-software] [--allow-restart-required] [--allow-feature-upgrade] [--json] [--execute]</code>: Una nuova ricerca precede l'anteprima. Gli aggiornamenti delle funzionalità richiedono entrambe le opzioni di autorizzazione e devono essere selezionati da soli. L'installazione richiede <code>--execute</code> e idoneità verificata dalle protezioni. <code>update-recover</code> non accetta opzioni e non installa mai aggiornamenti.",
    "cli_ref_workflow_form": "<code>workflow WORKFLOW [--recipes ID[,ID]] [--auto-repair] [--report OUTPUT.html|OUTPUT.txt] [--json]</code>: Usa <code>workflows</code> per i nomi validi e <code>recipes WORKFLOW</code> per gli ID delle ricette consentite. Sola lettura salvo che il flusso specifico supporti e riceva <code>--auto-repair</code>; ogni riparazione richiede comunque idoneità e verifica. Common-problems/full-scan rifiuta la riparazione automatica. I piani <code>--set KEY=VALUE</code> restano in sola lettura e non possono combinarsi con scelta di ricette, ambito o riparazione automatica. Il report richiede un percorso .html o .txt inesistente.",
    "cli_ref_workflow_scopes": "<code>workflow background-transfers [--all-users] [--json]</code>: Ispezione limitata dei trasferimenti senza riparazione automatica. Installed-apps accetta <code>--current-user</code>; app-packages accetta <code>--all-users</code> e <code>--include-provisioned</code>. Defender accetta <code>--skip-tpm</code>, <code>--skip-secure-boot</code> e <code>--skip-virtualization</code>. Il flusso available-updates accetta <code>--source Configured|WindowsUpdate|MicrosoftUpdate</code>, <code>--drivers</code> e <code>--no-software</code>; la sua opzione <code>--third-party</code> è disabilitata nella versione attuale.",
    "cli_ref_exit_limits": "Interpreta i codici insieme al risultato di ogni comando: leggere un catalogo, importare dati storici, esportare un piano o completare un'analisi non è un giudizio sullo stato del computer. Il codice 5 di symptom indica che la risoluzione del problema originale non è confermata. La convalida nativa può restituire 0 con scenari bloccati. Le prove incomplete devono restare incomplete. I comandi <code>recover</code> riconciliano l'operazione registrata senza autorizzarne un nuovo tentativo.",
    "cli_ref_full_link": "Per tutti i comandi, sintassi accettate, output, limiti e condizioni di esecuzione, apri la <a href=\"../help.html#cli\">guida completa alla riga di comando nella pagina di assistenza</a>. Questa pagina presenta i flussi principali."
  },
  "hu": {
    "cli_ref_discovery": "Parancsok keresése, hibafeltárás és helyi bizonyítékok",
    "cli_ref_conventions": "Minden alábbi parancs elé írja oda: <code>killerbench-cli</code>. A szóközös útvonalakat és szövegeket tegye idézőjelbe. A szögletes zárójel választható argumentumot jelöl, a függőleges vonal alternatívákat választ el. A <code>...</code> jelölésnél ismételje meg a teljes kapcsolót. A kapcsolók csak a megnevezett parancshoz tartoznak. A géppel olvasható névlistához használja a <code>capabilities</code> parancsot; ez a későbbi kiadásoknak fenntartott neveket is tartalmazza. Konzolos súgóhoz használja a <code>help</code>, <code>--help</code>, <code>-h</code> alakot, vagy ne adjon meg argumentumot.",
    "cli_ref_exceptions": "Az általános előnézeti szabálynak vannak kivételei: a <code>symptom run --repair</code>, a <code>workflow --auto-repair</code> és a <code>debloat-review</code> három energiagazdálkodási kapcsolója <code>--execute</code> nélkül is engedélyezi a dokumentált változtatásokat. A <code>validate-native</code> csak védett, eldobható környezetben idéz elő hibákat. A csomagexport, mentett tervek, naplók és jelentések is írnak helyi fájlokat. JSON csak a dokumentált helyeken érhető el; a csomagkeresés és ellenőrzés, az egyszerű szövegelemzés és több előnézet szöveget használ. A folyamat- és képességjelzések siker esetén is megjelenhetnek a szabványos hibakimeneten.",
    "cli_ref_profile_backup_limits": "A <code>profiles --backup-to</code> titkosítatlan profilbejegyzéseket támogat. Az EFS-titkosítású forrást még a biztonsági mentés céljának létrehozása előtt elutasítja.",
    "cli_ref_capabilities": "<code>capabilities [--json]</code>: Mindkét alakban JSON-t ad: <code>schemaVersion</code> (1), a szerelvény <code>version</code> értéke és rendezett, egyedi <code>commands</code> értékek (sztringek). Nem végez diagnosztikát vagy javítást. Csak az opcionális <code>--json</code> kapcsolót fogadja el; kilépési kód 0 siker esetén, 2 más argumentumoknál. A felsorolt név nem bizonyít natív támogatást vagy kiadásbeli elérhetőséget.",
    "cli_ref_pack": "<code>pack list | pack export PACK_ID OUTPUT.json | pack validate PACK.json</code>: Felsorolja a beépített csomagokat, a receptek képességcímkéit és a primitíveket; beépített csomagot exportál még nem létező kimeneti útvonalra; vagy helyi csomagot ellenőriz a Windows primitívkönyvtárával. Szöveges kimenet, receptet nem futtat. Az export létrehozza a szülőkönyvtárakat. Kódok: 0 siker, 2 érvénytelen argumentum, ismeretlen ID vagy létező kimenet, 3 érvénytelen vagy olvashatatlan csomag.",
    "cli_ref_symptom": "<code>symptom list | symptom search TEXT | symptom run SYMPTOM_ID [--repair] [--explicit] [--option NAME=VALUE]... [--answer NODE=KEY]... [--json]</code>: Felsorolja vagy keresi a támogatott tünetazonosítókat, majd bejár egy korlátozott hibafeltárási fát. Alapértelmezésben csak észlel. A <code>--repair</code> friss ellenőrzésekkel engedélyezi az automatikus csomagrecepteket; a <code>--explicit</code> külön megerősíti a kifejezett kapcsolókat igénylő recepteket, és megköveteli a <code>--repair</code> használatát. Minden recept legfeljebb egyszer alkalmazható; alapkorlátok: 40 lépés, 10 javítás, 30 perc. A megválaszolatlan kérdések nyitva maradnak. Helyi Triage naplót ír, szöveget vagy JSON-t ad. Kódok: 0 megoldva vagy kizárva, 3 megoldatlan vagy blokkolt, 4 újraindítás kell, 5 az összetevő javítása igazolt, de a tünet megszűnése nem, 130 megszakítva. Találat nélküli keresés: 3; érvénytelen bemenet: 2.",
    "cli_ref_investigate": "<code>investigate FILE_PATH [--json]</code>: Támogatott bizonyítékértékelési szabályokat alkalmaz helyi szövegnaplóra, mentett EVTX-archívumra vagy exportált Windows-események XML-dokumentumára, magyarázatokkal, hivatkozásokkal és következő lépésekkel. A szövegimport legfeljebb 1,000,000 karaktert és 10,000 feldolgozott bejegyzést olvas. Az EVTX Windows rendszert igényel, és a legújabb 200 rekordot tartja meg; az XML az első 200 rekordot, fájlsorrendben. Egyik eseményimport sem szűr dátumra; a korábbi bizonyíték nem igazolja a gép jelenlegi állapotát. Az elemzés megszakítási időkerete 15 másodperc. Alapból szöveg, <code>--json</code> esetén JSON. Kódok: 0 kész elemzés, 3 részleges bizonyíték, 1 olvashatatlan vagy nem támogatott bemenet, 2 érvénytelen argumentum, 130 megszakítás vagy időtúllépés. Nincs javítás.",
    "cli_ref_analyze": "<code>analyze TEXT_LOG_PATH [--json]</code>: Eltérő kódok megfigyeléseit nyeri ki egy szövegnaplóból okmegállapítás és módosítás nélkül. Legfeljebb 1,000,000 karaktert olvas, 256 kódot és kódonként nyolc hivatkozást tart meg; megszakítási időkerete 15 másodperc. Alapból szöveg, <code>--json</code> esetén JSON. Kódok: 0 teljes elemzés, 3 csonkolás, 1 bemeneti hiba, 2 érvénytelen argumentum, 130 megszakítás vagy időtúllépés.",
    "cli_ref_duplicate_files": "<code>duplicate-files FOLDER [--min-bytes N] [--max-files N] [--report]</code>: Helyi mappa ismétlődő fájljainak csak olvasható SHA-256-vizsgálata. Alapértékek: legalább egy bájt, 10,000 fájl; a minimum nulla is lehet, a fájlkorlát 1 és 100,000 közötti. Összesen legfeljebb 100 GiB kivonatolható. Alapból JSON, <code>--report</code> esetén szöveg; mindkettő felfedhet fájlútvonalakat. Nem jelöl ki fájlt törlésre. Kódok: 0 teljes, 3 hiányos, 1 vizsgálati/bemeneti hiba, 2 hibás kapcsolók, 130 megszakítva.",
    "cli_ref_large_files": "<code>large-files FOLDER [--min-bytes N] [--max-files N] [--limit N] [--report]</code>: Helyi mappa fájlméreteinek csak olvasható vizsgálata. Alapértékek: legalább 100 MiB, 10,000 vizsgált fájl és 500 megőrzött eredmény. A minimum pozitív; a fájlkorlát 1 és 100,000, az eredménykorlát 1 és 10,000 közötti. Alapból JSON, <code>--report</code> esetén szöveg; útvonalakat is tartalmaz. Kódok: 0 teljes, 3 hiányos, 1 vizsgálati/bemeneti hiba, 2 hibás kapcsolók, 130 megszakítva. Nincs takarítás.",
    "cli_ref_file_limits": "Mindkét mappavizsgálat kihagyja az újraelemzési pontokat (reparse points), és korlátozott bejárást használ: alapból 10,000 könyvtár, 1,024 várakozó könyvtár, 128 mélység és 30 másodperc. Az elérhetetlen tartalom vagy bármely bejárási, kivonatolási, fájl- vagy eredménykorlát elérése hiányos eredményt jelent. Ezek lefedettségi korlátok, nem a kihagyott fájlok biztonságának bizonyítékai.",
    "cli_ref_debloat_recover": "<code>debloat-recover power-plan|power-timers|hibernation --folder PATH [--json]</code>: Egy függő energiagazdálkodási művelettípus állapotát egyezteti a naplómappa teljes útvonalával. A függő rekordot tartalmazó mappát válassza, általában <code>%LOCALAPPDATA%\\KillerBench\\Debloat</code>. Mindig JSON-t ad, <code>--json</code> nélkül is; a folyamatjelzés a szabványos hibakimenetre kerül. Nem ismétli meg az energiabeállítás módosítását. A rendezett helyi rekordok archiválhatók. Kódok: 0 nincs függő rekord vagy igazolt állapot, 3 tisztázatlan bizonyíték, 1 fájl-/szolgáltatói hiba, 2 érvénytelen argumentum vagy relatív/hiányzó mappaútvonal, 130 megszakítva. Nincs <code>--execute</code> kapcsoló.",
    "cli_ref_gated": "Kiadási korlátozások és natív ellenőrzés eldobható környezetben",
    "cli_ref_third_party_updates": "<code>third-party-updates</code>: Fenntartott, csak olvasható alkalmazásfrissítés-keresés Microsoft.WinGet.Client használatával. A jelenlegi kiadásban letiltva; keresés nélkül 2 kódot és a KillerBench 1.1 elérhetőségi értesítését adja. Engedélyezve JSON-t ad; 0 teljes és elérhető keresés, 3 hiányos vagy nem elérhető, 1 szolgáltatói hiba, 130 megszakítás.",
    "cli_ref_third_party_update": "<code>third-party-update ID SOURCE VERSION [--accept-agreements] [--execute]</code>: Fenntartott frissítés egy pontosan meghatározott csomaghoz; jelenleg letiltva, kódja 2. Engedélyezve alapból a frissen felderített pontos ID, forrás és verzió előnézetét adja. A választás áttekintése után a végrehajtáshoz mindkét kapcsoló kell; megismétli a védelmi ellenőrzéseket és naplózza a kérést. JSON-kimenet; az alkalmasság és a végrehajtási eredmények egyértelműek maradnak. Ismételt vagy ismeretlen kapcsolókat elutasít. Nincs általános frissítés vagy hallgatólagos szerződéselfogadás.",
    "cli_ref_third_party_recover": "<code>third-party-update-recover</code>: Függő pontos verzió állapotának fenntartott egyeztetése; jelenleg letiltva, kódja 2. Engedélyezve a helyi ThirdPartyUpdates naplót olvassa, és a telepítés újrapróbálása nélkül ellenőrzi az állapotot. JSON-kimenet; 0 nincs függő rekord vagy igazolt állapot, 3 tisztázatlan bizonyíték, 130 megszakítás. Kapcsolókat nem fogad el.",
    "cli_ref_validate_native": "<code>validate-native RECIPE_ID SCENARIO_SUFFIX|all OUTPUT_DIR --disposable MACHINE_NAME</code>: Ellenőrzés szándékos hibák előidézésével, nem csak olvasható diagnosztika vagy előnézet. Eldobható Windows-gépen rendszergazdai jog, a gép pontos neve és <code>KILLERBENCH_DISPOSABLE=yes-this-machine-is-disposable</code> szükséges. Fejlesztői vagy ügyfélgépen soha ne használja. Futtatja a recept kiválasztott telepített forgatókönyvét vagy összes forgatókönyvét, megkísérli a helyreállítást, és az OUTPUT_DIR alá rekordokat és vizsgálati fájlokat ír. Szövegkimenet; 3 ha bármely forgatókönyv sikertelen, 0 ha egyik sem (blokkoltak ettől még lehetnek), 2 elutasító védelmi ellenőrzés vagy érvénytelen bemenet, 130 megszakítás. Minden eredményt és helyreállítási rekordot vizsgáljon meg; a 0 kód önmagában nem igazolja az ellenőrzés elfogadhatóságát.",
    "cli_ref_forms": "További elfogadott kapcsolók és munkafolyamat-alakok",
    "cli_ref_forms_intro": "Az alábbi kategorizált leírás minden nyilvános parancsot lefed. A bővített alakok a rövid bejegyzésekben könnyen elnézhető kapcsolókat is megőrzik.",
    "cli_ref_bitlocker_form": "<code>bitlocker-plan [--volume C:] [--operation Inspect|BackupRecovery|Encrypt|ResumeProtection] [--encryption Aes128|Aes256|XtsAes128|XtsAes256] [--used-space-only] [--backup File|ActiveDirectory|EntraId] [--backup-file PATH] [--inspect]</code>: Csak szöveges tervezés. A <code>--inspect</code> beolvassa a kiválasztott kötetet, nem módosítja a védelmet. Tényleges művelethez a külön védett parancsot használja.",
    "cli_ref_debloat_form": "<code>debloat-review --area AREA [--area AREA ...] [--all-profiles] [--keep-office-culture CULTURE] [--sleep-ac MINUTES --sleep-dc MINUTES --display-ac MINUTES --display-dc MINUTES] [--apply-high-performance|--apply-power-timers|--disable-hibernation] [--json]</code>: Alapból áttekintés. Minden kifejezett energiakapcsoló további <code>--execute</code> nélkül módosít. Pontosan egy végrehajtási kapcsolót és csak a hozzá tartozó területet válassza: HighPerformancePower, SleepAndDisplayTimers vagy Hibernation. Mind a négy időzítőérték együtt szükséges, egyenként 0 és 1440 perc között; a nulla jelentése Soha. A függő energiarekordokat egyezteti a módosítás megismétlése helyett. Alapból szöveg, <code>--json</code> esetén JSON; a blokkolt és nem igazolt bizonyítékokat egyértelműen jelzi.",
    "cli_ref_depot_form": "<code>depot-review [--microsoft-365] [--onedrive] [--teams] [--chrome] [--acrobat-reader] [--zoom] [--7zip] [--windows-updates] [--computer-name] [--local-admin] [--admin-review] [--browser-extensions] [--cleanup] [--edge] [--privacy] [--taskbar] [--start-menu] [--notifications] [--json]</code>: Válasszon legalább egy alkalmazás- vagy beállításcsoportot. Csak előkészítési áttekintés szövegben vagy JSON-ban; nincs telepítőletöltés, fióklétrehozás vagy beállításmódosítás.",
    "cli_ref_audio_form": "<code>device-check audio [--knowledge PACK_PATH ...] [--direction output|input] [--role console|multimedia|communications]</code>: A választható irány- és szerepszűrők csak a hangra vonatkoznak. Legfeljebb 32 csomaghoz ismételje meg a <code>--knowledge PATH</code> kapcsolót csomagonként. Csak olvasható JSON; egyik szűrő sem módosítja az alapértelmezett hangvégpontot.",
    "cli_ref_privacy_form": "<code>privacy-plan [--select AREA ...] [--inspect]</code>: Szöveges előnézet vagy csak olvasható rendszerleíróadatbázis-vizsgálat. A <code>privacy-setting</code> és <code>privacy-clipboard-history</code> mind a hat action, recover és undo alakja elfogadja a <code>--journal-folder PATH</code> kapcsolót is. Végrehajtáshoz és helyreállításhoz ugyanazt a mappát használja. A műveletek és visszavonások <code>--execute</code> nélkül csak előnézetek; a helyreállítás soha nem ismétli meg a változtatást.",
    "cli_ref_update_search_form": "<code>update-search [--source Configured|WindowsUpdate|MicrosoftUpdate] [--drivers] [--no-software] [--filter TITLE] [--downloaded-only] [--classification GUID] [--product GUID]</code>: Csak olvasható keresés JSON-kimenettel és pontosan egyező azonosítókkal. A forrás kiválasztása nem engedélyez letöltést vagy telepítést.",
    "cli_ref_update_plan_form": "<code>update-plan --select GUID:REVISION [--select GUID:REVISION ...] [--source Configured|WindowsUpdate|MicrosoftUpdate] [--drivers] [--no-software] [--allow-restart-required] [--allow-feature-upgrade] [--json] [--execute]</code>: Az előnézetet friss keresés előzi meg. A funkciófrissítésekhez mindkét engedélyező kapcsoló kell, és csak önmagukban választhatók. A telepítéshez <code>--execute</code> és védelmi ellenőrzésekkel igazolt alkalmasság szükséges. A <code>update-recover</code> nem fogad el kapcsolót, és soha nem telepít frissítést.",
    "cli_ref_workflow_form": "<code>workflow WORKFLOW [--recipes ID[,ID]] [--auto-repair] [--report OUTPUT.html|OUTPUT.txt] [--json]</code>: Érvényes nevekhez <code>workflows</code>, engedélyezett receptazonosítókhoz <code>recipes WORKFLOW</code> használható. Csak olvasható, kivéve ha a célzott munkafolyamat támogatja és megkapja a <code>--auto-repair</code> kapcsolót; minden javítás továbbra is alkalmasságot és ellenőrzést igényel. A Common-problems/full-scan elutasítja az automatikus javítást. A <code>--set KEY=VALUE</code> tervek csak olvashatók, és nem kombinálhatók receptválasztással, hatókörválasztással vagy automatikus javítással. A jelentéshez még nem létező .html vagy .txt útvonal kell.",
    "cli_ref_workflow_scopes": "<code>workflow background-transfers [--all-users] [--json]</code>: Korlátozott átviteli vizsgálat automatikus javítás nélkül. Az Installed-apps elfogadja a <code>--current-user</code> kapcsolót; az app-packages a <code>--all-users</code> és <code>--include-provisioned</code> kapcsolót. A Defender a <code>--skip-tpm</code>, <code>--skip-secure-boot</code> és <code>--skip-virtualization</code> kapcsolót. Az available-updates munkafolyamat a <code>--source Configured|WindowsUpdate|MicrosoftUpdate</code>, <code>--drivers</code> és <code>--no-software</code> kapcsolót fogadja; a <code>--third-party</code> kapcsoló a jelenlegi kiadásban letiltott.",
    "cli_ref_exit_limits": "A kilépési kódot a parancs eredményével együtt értelmezze: a sikeres katalógusolvasás, történeti import, tervexport vagy elemzés nem állapotminősítés. A symptom 5 kódja azt jelenti, hogy az eredeti probléma megszűnése nem igazolt. A natív ellenőrzés blokkolt forgatókönyvekkel is adhat 0 kódot. A hiányos bizonyíték hiányos marad. A <code>recover</code> parancsok a rögzített művelet állapotát egyeztetik, nem engedélyezik az újrapróbálását.",
    "cli_ref_full_link": "Minden parancs, elfogadott szintaxis, kimenet, korlát és végrehajtási feltétel megtalálható a <a href=\"../help.html#cli\">súgóoldal teljes parancssori leírásában</a>. Ez az oldal a fő munkafolyamatokat mutatja be."
  },
  "ja": {
    "cli_ref_discovery": "コマンドの検索、問題の切り分け、ローカルの証拠",
    "cli_ref_conventions": "以下の各コマンドの前に <code>killerbench-cli</code> を付けてください。空白を含むパスやテキストは引用符で囲みます。角括弧は省略可能な引数、縦棒は選択肢を表します。<code>...</code> の場合はオプション全体を繰り返します。オプションは記載されたコマンド専用です。機械可読の名前一覧には <code>capabilities</code> を使用します。公開制限により予約されている名前も含まれます。コンソールの案内は <code>help</code>、<code>--help</code>、<code>-h</code>、または引数なしで表示できます。",
    "cli_ref_exceptions": "通常のプレビュー動作には例外があります。<code>symptom run --repair</code>、<code>workflow --auto-repair</code>、および <code>debloat-review</code> の3つの電源オプションは、<code>--execute</code> なしで記載の変更を許可します。<code>validate-native</code> は保護された使い捨て環境でのみ障害を注入します。パックのエクスポート、保存した計画、ジャーナル、レポートもローカルファイルに書き込みます。JSON は対応が記載された場合のみ使用できます。パックの検出と検証、プレーンテキストの分析、一部のプレビューはテキスト出力です。成功時でも進行状況や機能に関する通知が標準エラー出力に表示されることがあります。",
    "cli_ref_profile_backup_limits": "<code>profiles --backup-to</code> は暗号化されていないプロファイル項目に対応します。EFS で暗号化されたソースは、バックアップ先の作成前に拒否されます。",
    "cli_ref_capabilities": "<code>capabilities [--json]</code>: どちらの形式でも JSON を返します。内容は <code>schemaVersion</code> (1)、アセンブリの <code>version</code>、並べ替え済みで重複のない <code>commands</code> (文字列) です。診断や修復は行いません。省略可能な <code>--json</code> のみ受け付けます。終了コードは成功時 0、その他の引数では 2。名前の記載はネイティブ対応や現行リリースでの利用可否を保証しません。",
    "cli_ref_pack": "<code>pack list | pack export PACK_ID OUTPUT.json | pack validate PACK.json</code>: 組み込みパック、レシピの機能ラベル、プリミティブを一覧表示するか、組み込みパックを未作成の出力パスにエクスポートするか、ローカルパックを Windows プリミティブライブラリに照らして検証します。テキスト出力で、レシピは実行しません。エクスポート時に親ディレクトリを作成します。終了コード: 0 成功、2 無効な引数・不明な ID・既存の出力、3 無効または読み取り不能なパック。",
    "cli_ref_symptom": "<code>symptom list | symptom search TEXT | symptom run SYMPTOM_ID [--repair] [--explicit] [--option NAME=VALUE]... [--answer NODE=KEY]... [--json]</code>: 対応する症状 ID の一覧表示や検索を行い、制限付きの切り分けツリーを1つ実行します。既定では検出のみです。<code>--repair</code> は最新のチェックを伴うパックレシピの自動実行を許可します。<code>--explicit</code> は明示的なオプションが必要なレシピを追加で確認し、<code>--repair</code> が必要です。各レシピは最大1回適用されます。既定の上限は 40 ステップ、10 回の修復、30 分です。未回答の質問は未解決のまま残ります。ローカルの Triage ジャーナルに書き込み、テキストまたは JSON を返します。終了コード: 0 解決または除外、3 未解決またはブロック、4 再起動が必要、5 コンポーネントの修復は検証済みだが症状の解消は未確認、130 キャンセル。検索結果なしは 3、無効な入力は 2。",
    "cli_ref_investigate": "<code>investigate FILE_PATH [--json]</code>: ローカルのテキストログ、保存された EVTX アーカイブ、エクスポートされた Windows イベントの XML 文書に対応する証拠ルールを適用し、説明、参考情報、次の手順を示します。テキスト読み込みは最大 1,000,000 文字、解析した項目は最大 10,000 件です。EVTX には Windows が必要で最新 200 件を保持します。XML はファイル順で最初の 200 件を保持します。どちらのイベント読み込みも日付フィルターを適用せず、過去の証拠は現在のマシンの正常性を証明しません。分析のキャンセル時間枠は 15 秒です。既定はテキスト、<code>--json</code> で JSON。終了コード: 0 分析完了、3 部分的な証拠、1 読み取り不能または未対応の入力、2 無効な引数、130 キャンセルまたはタイムアウト。修復は行いません。",
    "cli_ref_analyze": "<code>analyze TEXT_LOG_PATH [--json]</code>: 原因の診断や変更を行わず、1つのテキストログから異なるコードの観測情報を抽出します。最大 1,000,000 文字を読み、最大 256 コードとコードごとに8件の参考情報を保持します。キャンセル時間枠は 15 秒です。既定はテキスト、<code>--json</code> で JSON。終了コード: 0 完全な分析、3 切り詰めあり、1 入力エラー、2 無効な引数、130 キャンセルまたはタイムアウト。",
    "cli_ref_duplicate_files": "<code>duplicate-files FOLDER [--min-bytes N] [--max-files N] [--report]</code>: 1つのローカルフォルダーを SHA-256 で読み取り専用の重複チェックにかけます。既定は最小1バイト、10,000 ファイル。最小値はゼロも可、ファイル上限は 1 から 100,000。ハッシュ計算は合計 100 GiB までです。既定は JSON、<code>--report</code> でテキスト。どちらもファイルパスを公開する場合があります。削除対象の選択は行いません。終了コード: 0 完了、3 不完全、1 スキャンまたは入力エラー、2 オプションの形式不正、130 キャンセル。",
    "cli_ref_large_files": "<code>large-files FOLDER [--min-bytes N] [--max-files N] [--limit N] [--report]</code>: 1つのローカルフォルダーのサイズを読み取り専用で調べます。既定は最小 100 MiB、調査対象 10,000 ファイル、保持する結果 500 件。最小値は正数、ファイル上限は 1 から 100,000、結果上限は 1 から 10,000 です。既定は JSON、<code>--report</code> でテキスト。出力にはファイルパスが含まれます。終了コード: 0 完了、3 不完全、1 スキャンまたは入力エラー、2 オプションの形式不正、130 キャンセル。クリーンアップは行いません。",
    "cli_ref_file_limits": "両方のフォルダーチェックは再解析ポイントをスキップし、探索を制限します。既定の上限は 10,000 ディレクトリ、待機中 1,024 ディレクトリ、深さ 128、30 秒です。アクセス不能な内容や、探索・ハッシュ・ファイル・結果のいずれかの上限に達した場合は不完全のままとなります。これらは調査範囲の制限であり、除外されたファイルの安全性の証拠ではありません。",
    "cli_ref_debloat_recover": "<code>debloat-recover power-plan|power-timers|hibernation --folder PATH [--json]</code>: ジャーナルフォルダーの完全パスを使い、保留中の電源操作のうち1種類の状態を照合します。保留レコードがある同じフォルダーを指定します。通常は <code>%LOCALAPPDATA%\\KillerBench\\Debloat</code> です。<code>--json</code> の有無にかかわらず常に JSON を返し、進行状況は標準エラー出力に送ります。電源の変更を繰り返しません。解決済みのローカルレコードはアーカイブされることがあります。終了コード: 0 保留レコードなしまたは状態検証済み、3 未解決の証拠、1 ファイルまたはプロバイダーのエラー、2 無効な引数または相対パス・存在しないフォルダーパス、130 キャンセル。<code>--execute</code> オプションはありません。",
    "cli_ref_gated": "リリースによる利用制限と使い捨て環境でのネイティブ検証",
    "cli_ref_third_party_updates": "<code>third-party-updates</code>: Microsoft.WinGet.Client による読み取り専用のアプリ更新検出用に予約されています。現行リリースでは無効で、検出せず KillerBench 1.1 の提供予定通知と終了コード 2 を返します。有効化後は JSON を出力します。完全かつ利用可能な検出は 0、不完全または利用不能は 3、プロバイダー失敗は 1、キャンセルは 130。",
    "cli_ref_third_party_update": "<code>third-party-update ID SOURCE VERSION [--accept-agreements] [--execute]</code>: 厳密に指定されたパッケージの更新用に予約されています。現在は無効で終了コード 2。有効化後は、新たに検出した正確な ID・ソース・バージョンのプレビューが既定です。選択内容の確認後、実行には両方のオプションが必要で、保護チェックを再実行して要求をジャーナルに記録します。JSON 出力。実行資格と実行結果は明示されます。重複または不明なフラグは拒否します。一括アップグレードや暗黙の契約同意は行いません。",
    "cli_ref_third_party_recover": "<code>third-party-update-recover</code>: 保留中の厳密なバージョンの状態照合用に予約されています。現在は無効で終了コード 2。有効化後はローカルの ThirdPartyUpdates ジャーナルを読み、インストールを再試行せず状態を検証します。JSON 出力。終了コード: 0 保留レコードなしまたは状態検証済み、3 未解決の証拠、130 キャンセル。オプションは受け付けません。",
    "cli_ref_validate_native": "<code>validate-native RECIPE_ID SCENARIO_SUFFIX|all OUTPUT_DIR --disposable MACHINE_NAME</code>: 障害注入による検証です。読み取り専用の診断やプレビューではありません。使い捨ての Windows マシン上で管理者権限、正確なマシン名、<code>KILLERBENCH_DISPOSABLE=yes-this-machine-is-disposable</code> が必要です。開発用や顧客のマシンでは絶対に使用しないでください。レシピの選択したインストール済みシナリオ、またはすべてのシナリオを実行し、復元を試み、OUTPUT_DIR に記録と成果物を書き込みます。テキスト出力。終了コード: 3 いずれかのシナリオが失敗、0 失敗なし (ブロックされたシナリオが残る場合あり)、2 保護条件による拒否または無効な入力、130 キャンセル。すべての結果と復元記録を確認してください。コード 0 だけで検証合格にはなりません。",
    "cli_ref_forms": "追加で受け付けるオプションとワークフロー形式",
    "cli_ref_forms_intro": "以下のカテゴリ別リファレンスはすべての公開コマンドを網羅します。ここでは短い説明で見落としやすいオプションも含めた形式を示します。",
    "cli_ref_bitlocker_form": "<code>bitlocker-plan [--volume C:] [--operation Inspect|BackupRecovery|Encrypt|ResumeProtection] [--encryption Aes128|Aes256|XtsAes128|XtsAes256] [--used-space-only] [--backup File|ActiveDirectory|EntraId] [--backup-file PATH] [--inspect]</code>: テキストによる計画のみです。<code>--inspect</code> は選択したボリュームを読み取り、保護設定は変更しません。実際の操作には専用の保護付きコマンドを使用してください。",
    "cli_ref_debloat_form": "<code>debloat-review --area AREA [--area AREA ...] [--all-profiles] [--keep-office-culture CULTURE] [--sleep-ac MINUTES --sleep-dc MINUTES --display-ac MINUTES --display-dc MINUTES] [--apply-high-performance|--apply-power-timers|--disable-hibernation] [--json]</code>: 既定は確認のみです。明示的な各電源オプションは、追加の <code>--execute</code> なしで変更を実行します。実行オプションを正確に1つ、その対応する領域だけを選択します: HighPerformancePower、SleepAndDisplayTimers、Hibernation。4つのタイマー値はすべて同時に指定し、それぞれ 0 から 1440 分です。ゼロは「なし」を意味します。保留中の電源レコードがあれば変更を繰り返さず状態を照合します。既定はテキスト、<code>--json</code> で JSON。ブロックされた証拠や未検証の証拠は明示されます。",
    "cli_ref_depot_form": "<code>depot-review [--microsoft-365] [--onedrive] [--teams] [--chrome] [--acrobat-reader] [--zoom] [--7zip] [--windows-updates] [--computer-name] [--local-admin] [--admin-review] [--browser-extensions] [--cleanup] [--edge] [--privacy] [--taskbar] [--start-menu] [--notifications] [--json]</code>: アプリケーションまたは設定グループを1つ以上選択します。テキストまたは JSON による導入準備の確認のみで、インストーラーのダウンロード、アカウント作成、設定変更は行いません。",
    "cli_ref_audio_form": "<code>device-check audio [--knowledge PACK_PATH ...] [--direction output|input] [--role console|multimedia|communications]</code>: 省略可能な方向・役割フィルターはオーディオにのみ適用されます。最大 32 パックのそれぞれに <code>--knowledge PATH</code> を繰り返します。読み取り専用の JSON。どちらのフィルターも既定のオーディオエンドポイントを変更しません。",
    "cli_ref_privacy_form": "<code>privacy-plan [--select AREA ...] [--inspect]</code>: テキストのプレビューまたはレジストリの読み取り専用検査。<code>privacy-setting</code> と <code>privacy-clipboard-history</code> の action、recover、undo の計6形式は <code>--journal-folder PATH</code> も受け付けます。実行と回復には同じフォルダーを使用してください。action と undo は <code>--execute</code> がなければプレビューのみで、recover は変更を繰り返しません。",
    "cli_ref_update_search_form": "<code>update-search [--source Configured|WindowsUpdate|MicrosoftUpdate] [--drivers] [--no-software] [--filter TITLE] [--downloaded-only] [--classification GUID] [--product GUID]</code>: 読み取り専用の検出で JSON と完全一致の識別情報を返します。ソースの選択はダウンロードやインストールを許可しません。",
    "cli_ref_update_plan_form": "<code>update-plan --select GUID:REVISION [--select GUID:REVISION ...] [--source Configured|WindowsUpdate|MicrosoftUpdate] [--drivers] [--no-software] [--allow-restart-required] [--allow-feature-upgrade] [--json] [--execute]</code>: プレビュー前に再検出します。機能アップグレードには両方の許可フラグが必要で、単独で選択する必要があります。インストールには <code>--execute</code> と保護チェックによる適格性が必要です。<code>update-recover</code> はオプションを受け付けず、更新をインストールしません。",
    "cli_ref_workflow_form": "<code>workflow WORKFLOW [--recipes ID[,ID]] [--auto-repair] [--report OUTPUT.html|OUTPUT.txt] [--json]</code>: 有効な名前には <code>workflows</code>、許可されたレシピ ID には <code>recipes WORKFLOW</code> を使用します。対象ワークフローが <code>--auto-repair</code> に対応し、かつ指定された場合以外は読み取り専用です。各修復には引き続き適格性と検証が必要です。Common-problems/full-scan は自動修復を拒否します。<code>--set KEY=VALUE</code> 計画は読み取り専用のままで、レシピ選択、範囲選択、自動修復と組み合わせられません。レポートには未作成の .html または .txt パスが必要です。",
    "cli_ref_workflow_scopes": "<code>workflow background-transfers [--all-users] [--json]</code>: 制限付きの転送検査で、自動修復は行いません。Installed-apps は <code>--current-user</code>、app-packages は <code>--all-users</code> と <code>--include-provisioned</code> を受け付けます。Defender は <code>--skip-tpm</code>、<code>--skip-secure-boot</code>、<code>--skip-virtualization</code> を受け付けます。available-updates ワークフローは <code>--source Configured|WindowsUpdate|MicrosoftUpdate</code>、<code>--drivers</code>、<code>--no-software</code> を受け付けます。現行リリースでは <code>--third-party</code> は無効です。",
    "cli_ref_exit_limits": "終了コードは各コマンドの結果と併せて判断してください。カタログ読み取り、過去データのインポート、計画のエクスポート、分析の成功は正常性の判定ではありません。symptom のコード 5 は元の問題の解消が未確認であることを示します。ネイティブ検証はブロックされたシナリオがあっても 0 を返す場合があります。不完全な証拠は不完全のままとして扱います。<code>recover</code> コマンドは記録された操作の状態を照合するもので、再試行を許可するものではありません。",
    "cli_ref_full_link": "各コマンドの対応構文、出力、制限、実行条件は、<a href=\"../help.html#cli\">ヘルプページの完全なコマンドラインリファレンス</a>を参照してください。このページでは主なワークフローを紹介します。"
  },
  "kk": {
    "cli_ref_discovery": "Пәрмендерді іздеу, ақауды саралау және жергілікті деректер",
    "cli_ref_conventions": "Төмендегі әр пәрменнің алдына <code>killerbench-cli</code> жазыңыз. Бос орны бар жолдар мен мәтінді тырнақшаға алыңыз. Тік жақша міндетті емес аргументтерді, тік сызық баламаларды білдіреді. <code>...</code> көрсетілсе, бүкіл параметрді қайталаңыз. Параметр тек аталған пәрменге тиесілі. Машина оқи алатын атаулар тізімін алу үшін <code>capabilities</code> пайдаланыңыз; онда кейінгі шығарылымдарға сақталған атаулар да бар. Консоль анықтамасы үшін <code>help</code>, <code>--help</code>, <code>-h</code> пайдаланыңыз немесе аргумент бермеңіз.",
    "cli_ref_exceptions": "Жалпы алдын ала қарау ережесінің ерекшеліктері бар: <code>symptom run --repair</code>, <code>workflow --auto-repair</code> және <code>debloat-review</code> пәрменінің үш қуат параметрі құжатталған өзгерістерге <code>--execute</code> параметрінсіз рұқсат береді. <code>validate-native</code> тек қорғалған, сынақтан кейін жойылатын ортада әдейі ақау енгізеді. Пакет экспорты, сақталған жоспарлар, журналдар мен есептер де жергілікті файлдар жазады. JSON тек құжатта көрсетілген жерде бар; пакеттерді табу мен тексеру, жай мәтінді талдау және кейбір алдын ала қараулар мәтін шығарады. Пәрмен сәтті орындалса да, орындалу барысы мен мүмкіндіктер туралы хабарлар стандартты қате ағынында көрінуі мүмкін.",
    "cli_ref_profile_backup_limits": "<code>profiles --backup-to</code> шифрланбаған профиль жазбаларын қолдайды. EFS арқылы шифрланған дереккөз сақтық көшірме орны жасалмай тұрып қабылданбайды.",
    "cli_ref_capabilities": "<code>capabilities [--json]</code>: Екі нұсқада да JSON қайтарады: <code>schemaVersion</code> (1), жинақтың <code>version</code> мәні және сұрыпталған, қайталанбайтын <code>commands</code> (жолдар). Диагностика не жөндеу жүргізбейді. Тек міндетті емес <code>--json</code> параметрін қабылдайды; сәтті болса шығу коды 0, басқа аргументтерде 2. Атаудың тізімде болуы жергілікті жүйе қолдауын немесе осы шығарылымда қолжетімділігін дәлелдемейді.",
    "cli_ref_pack": "<code>pack list | pack export PACK_ID OUTPUT.json | pack validate PACK.json</code>: Кіріктірілген пакеттерді, рецепт мүмкіндіктерінің белгілерін және примитивтерді тізімдейді; кіріктірілген пакетті әлі жоқ шығыс жолына экспорттайды; немесе жергілікті пакетті Windows примитивтер кітапханасына сай тексереді. Мәтіндік шығыс, рецепттер орындалмайды. Экспорт ата-аналық каталогтарды жасайды. Кодтар: 0 сәтті, 2 жарамсыз аргумент, белгісіз ID немесе бар шығыс, 3 жарамсыз не оқылмайтын пакет.",
    "cli_ref_symptom": "<code>symptom list | symptom search TEXT | symptom run SYMPTOM_ID [--repair] [--explicit] [--option NAME=VALUE]... [--answer NODE=KEY]... [--json]</code>: Қолдау көрсетілетін симптом ID тізімін береді не іздейді, содан кейін шектелген саралау ағашын орындайды. Әдепкіде тек анықтайды. <code>--repair</code> жаңа тексерулермен автоматты пакет рецепттеріне рұқсат береді; <code>--explicit</code> айқын параметрлерді қажет ететін рецепттерді қосымша растайды және <code>--repair</code> талап етеді. Әр рецепт ең көбі бір рет қолданылады; әдепкі шектер: 40 қадам, 10 жөндеу, 30 минут. Жауапсыз сұрақтар ашық қалады. Жергілікті Triage журналына жазады, мәтін не JSON қайтарады. Кодтар: 0 шешілді немесе ықтималдық жоққа шығарылды, 3 шешілмеді не бұғатталды, 4 қайта іске қосу керек, 5 құрамдас жөндеуі тексерілді, бірақ симптомның жоғалғаны расталмады, 130 тоқтатылды. Іздеуде сәйкестік жоқ болса 3, жарамсыз кірісте 2.",
    "cli_ref_investigate": "<code>investigate FILE_PATH [--json]</code>: Жергілікті мәтін журналына, сақталған EVTX мұрағатына немесе экспортталған Windows оқиғаларының XML құжатына қолдау көрсетілетін деректерді бағалау ережелерін қолданып, түсіндірме, сілтемелер және келесі қадамдарды береді. Мәтін импорты ең көбі 1,000,000 таңба мен 10,000 талданған жазбаны оқиды. EVTX үшін Windows қажет, ең жаңа 200 жазба сақталады; XML файл ретіндегі алғашқы 200 жазбаны сақтайды. Оқиғалардың екі импорты да күн бойынша сүзбейді; ескі деректер компьютердің қазіргі күйін дәлелдемейді. Талдауды тоқтату уақытының шегі 15 секунд. Әдепкіде мәтін, <code>--json</code> арқылы JSON. Кодтар: 0 талдау аяқталды, 3 ішінара деректер, 1 оқылмайтын не қолдау көрсетілмейтін кіріс, 2 жарамсыз аргументтер, 130 тоқтатылды не уақыт бітті. Жөндеу жүргізбейді.",
    "cli_ref_analyze": "<code>analyze TEXT_LOG_PATH [--json]</code>: Себепті анықтамай және өзгеріс жасамай, бір мәтін журналынан әртүрлі кодтарға қатысты бақылауларды шығарады. Ең көбі 1,000,000 таңбаны оқиды, 256 код пен әр кодқа сегіз сілтемені сақтайды; тоқтату уақытының шегі 15 секунд. Әдепкіде мәтін, <code>--json</code> арқылы JSON. Кодтар: 0 толық талдау, 3 қысқартылды, 1 кіріс қатесі, 2 жарамсыз аргументтер, 130 тоқтатылды не уақыт бітті.",
    "cli_ref_duplicate_files": "<code>duplicate-files FOLDER [--min-bytes N] [--max-files N] [--report]</code>: Бір жергілікті қалтадағы қайталанатын файлдарды SHA-256 арқылы тек оқу режимінде тексереді. Әдепкі мәндер: ең азы бір байт, 10,000 файл; ең аз мән нөл болуы мүмкін, файл шегі 1 мен 100,000 арасында. Хэштеу жалпы 100 GiB көлемімен шектеледі. Әдепкіде JSON, <code>--report</code> арқылы мәтін; екеуі де файл жолдарын көрсетуі мүмкін. Жоюға файл таңдалмайды. Кодтар: 0 толық, 3 толық емес, 1 тексеру/кіріс қатесі, 2 қате пішімделген параметрлер, 130 тоқтатылды.",
    "cli_ref_large_files": "<code>large-files FOLDER [--min-bytes N] [--max-files N] [--limit N] [--report]</code>: Бір жергілікті қалтадағы өлшемдерді тек оқу режимінде тексереді. Әдепкі мәндер: ең азы 100 MiB, 10,000 тексерілген файл, 500 сақталған нәтиже. Ең аз мән оң болуы керек; файл шегі 1 мен 100,000, нәтиже шегі 1 мен 10,000 арасында. Әдепкіде JSON, <code>--report</code> арқылы мәтін; шығыста файл жолдары бар. Кодтар: 0 толық, 3 толық емес, 1 тексеру/кіріс қатесі, 2 қате пішімделген параметрлер, 130 тоқтатылды. Тазалау жүргізбейді.",
    "cli_ref_file_limits": "Қалталарды екі тексеру де қайта талдау нүктелерін (reparse points) өткізіп, аралауды шектейді: әдепкіде 10,000 каталог, кезектегі 1,024 каталог, тереңдік 128 және 30 секунд. Қолжетімсіз мазмұн немесе аралау, хэштеу, файл не нәтиже шегіне жету тексерудің толық еместігін білдіреді. Бұлар қамту шектері, өткізіп жіберілген файлдардың қауіпсіздік дәлелі емес.",
    "cli_ref_debloat_recover": "<code>debloat-recover power-plan|power-timers|hibernation --folder PATH [--json]</code>: Журнал қалтасының толық жолы арқылы күтудегі қуат операциясының бір түрінің күйін салыстырып тексереді. Күтудегі жазба тұрған сол қалтаны таңдаңыз, әдетте <code>%LOCALAPPDATA%\\KillerBench\\Debloat</code>. <code>--json</code> болса да, болмаса да, әрқашан JSON қайтарады; орындалу барысы стандартты қате ағынына жіберіледі. Қуат өзгерісін қайталамайды. Шешілген жергілікті жазбалар мұрағатталуы мүмкін. Кодтар: 0 күтудегі жазба жоқ не күй тексерілді, 3 анықталмаған деректер, 1 файл/провайдер қатесі, 2 жарамсыз аргументтер не салыстырмалы/жоқ қалта жолы, 130 тоқтатылды. <code>--execute</code> параметрі жоқ.",
    "cli_ref_gated": "Шығарылым шектеулері және жойылатын сынақ ортасында нативті тексеру",
    "cli_ref_third_party_updates": "<code>third-party-updates</code>: Microsoft.WinGet.Client арқылы қолданба жаңартуларын тек оқу режимінде іздеуге сақталған пәрмен. Қазіргі шығарылымда өшірулі; іздемей, KillerBench 1.1 қолжетімділік хабарымен 2 кодын береді. Қосылғанда JSON шығарады; 0 толық әрі қолжетімді іздеу, 3 толық емес не қолжетімсіз, 1 провайдер қатесі, 130 тоқтату.",
    "cli_ref_third_party_update": "<code>third-party-update ID SOURCE VERSION [--accept-agreements] [--execute]</code>: Дәл көрсетілген пакетті жаңартуға сақталған пәрмен; қазір өшірулі, коды 2. Қосылғанда әдепкіде жаңадан табылған нақты ID, дереккөз және нұсқаның алдын ала көрінісін береді. Таңдауды қарағаннан кейін орындау екі параметрді де талап етеді, қорғаныс тексерулерін қайталайды және сұрауды журналға жазады. JSON шығысы; жарамдылық пен орындалу нәтижелері айқын көрсетіледі. Қайталанатын не белгісіз жалаушалар қабылданбайды. Жаппай жаңарту немесе келісімдерді үнсіз қабылдау жоқ.",
    "cli_ref_third_party_recover": "<code>third-party-update-recover</code>: Күтудегі нақты нұсқаның күйін салыстыруға сақталған пәрмен; қазір өшірулі, коды 2. Қосылғанда жергілікті ThirdPartyUpdates журналын оқып, орнатуды қайталамай күйді тексереді. JSON шығысы; 0 күтудегі жазба жоқ не күй тексерілді, 3 анықталмаған деректер, 130 тоқтату. Параметрлер қабылдамайды.",
    "cli_ref_validate_native": "<code>validate-native RECIPE_ID SCENARIO_SUFFIX|all OUTPUT_DIR --disposable MACHINE_NAME</code>: Әдейі ақау енгізу арқылы тексеру, тек оқу диагностикасы не алдын ала қарау емес. Сынақтан кейін жойылатын Windows компьютерінде әкімші құқығы, компьютердің дәл атауы және <code>KILLERBENCH_DISPOSABLE=yes-this-machine-is-disposable</code> қажет. Әзірлеу не тұтынушы компьютерін ешқашан пайдаланбаңыз. Рецепттің таңдалған орнатылған сценарийін немесе барлық сценарийлерін орындайды, қалпына келтіруге тырысады және OUTPUT_DIR ішіне жазбалар мен тексеру файлдарын жазады. Мәтіндік шығыс; 3 кез келген сценарий сәтсіз болса, 0 ешқайсысы сәтсіз болмаса (бұғатталған сценарийлер қалуы мүмкін), 2 қорғаныс тексеруі бас тартса не кіріс жарамсыз болса, 130 тоқтатылса. Әр нәтиже мен қалпына келтіру жазбасын тексеріңіз; жалғыз 0 коды тексеруден өтуге жеткіліксіз.",
    "cli_ref_forms": "Қосымша қабылданатын параметрлер мен жұмыс ағынының нұсқалары",
    "cli_ref_forms_intro": "Төмендегі санатталған анықтама барлық ашық пәрмендерді қамтиды. Кеңейтілген нұсқалар қысқа сипаттамаларда байқалмай қалуы мүмкін параметрлерді де сақтайды.",
    "cli_ref_bitlocker_form": "<code>bitlocker-plan [--volume C:] [--operation Inspect|BackupRecovery|Encrypt|ResumeProtection] [--encryption Aes128|Aes256|XtsAes128|XtsAes256] [--used-space-only] [--backup File|ActiveDirectory|EntraId] [--backup-file PATH] [--inspect]</code>: Тек мәтіндік жоспарлау. <code>--inspect</code> таңдалған томды оқиды, қорғаныс параметрлерін өзгертпейді. Нақты операцияға арнайы қорғалған пәрменді пайдаланыңыз.",
    "cli_ref_debloat_form": "<code>debloat-review --area AREA [--area AREA ...] [--all-profiles] [--keep-office-culture CULTURE] [--sleep-ac MINUTES --sleep-dc MINUTES --display-ac MINUTES --display-dc MINUTES] [--apply-high-performance|--apply-power-timers|--disable-hibernation] [--json]</code>: Әдепкіде тек шолу. Әр айқын қуат параметрі қосымша <code>--execute</code> талап етпей өзгертеді. Дәл бір орындау параметрін және тек сәйкес аймағын таңдаңыз: HighPerformancePower, SleepAndDisplayTimers немесе Hibernation. Төрт таймер мәні бірге қажет, әрқайсысы 0 мен 1440 минут арасында; нөл «Ешқашан» дегенді білдіреді. Күтудегі қуат жазбалары болса, өзгеріс қайталанбай, күй салыстырылады. Әдепкіде мәтін, <code>--json</code> арқылы JSON; бұғатталған не тексерілмеген деректер айқын белгіленеді.",
    "cli_ref_depot_form": "<code>depot-review [--microsoft-365] [--onedrive] [--teams] [--chrome] [--acrobat-reader] [--zoom] [--7zip] [--windows-updates] [--computer-name] [--local-admin] [--admin-review] [--browser-extensions] [--cleanup] [--edge] [--privacy] [--taskbar] [--start-menu] [--notifications] [--json]</code>: Кемінде бір қолданбаны не баптау тобын таңдаңыз. Тек мәтін не JSON түріндегі бастапқы дайындау шолуы; орнатқыш жүктемейді, тіркелгі жасамайды, баптауды өзгертпейді.",
    "cli_ref_audio_form": "<code>device-check audio [--knowledge PACK_PATH ...] [--direction output|input] [--role console|multimedia|communications]</code>: Міндетті емес бағыт пен рөл сүзгілері тек аудиоға қолданылады. Ең көбі 32 пакеттің әрқайсысына <code>--knowledge PATH</code> қайталаңыз. Тек оқу режиміндегі JSON; ешбір сүзгі әдепкі аудио соңғы нүктесін өзгертпейді.",
    "cli_ref_privacy_form": "<code>privacy-plan [--select AREA ...] [--inspect]</code>: Мәтіндік алдын ала қарау немесе тізілімді тек оқу режимінде тексеру. <code>privacy-setting</code> және <code>privacy-clipboard-history</code> пәрмендерінің action, recover және undo деген алты нұсқасы да <code>--journal-folder PATH</code> қабылдайды. Орындау мен қалпына келтіруге бір қалтаны пайдаланыңыз. <code>--execute</code> болмаса, action және undo тек алдын ала қарау болады; recover өзгерісті ешқашан қайталамайды.",
    "cli_ref_update_search_form": "<code>update-search [--source Configured|WindowsUpdate|MicrosoftUpdate] [--drivers] [--no-software] [--filter TITLE] [--downloaded-only] [--classification GUID] [--product GUID]</code>: JSON шығысы мен дәл сәйкес сәйкестендіргіштері бар тек оқу режиміндегі іздеу. Дереккөзді таңдау жүктеуге не орнатуға рұқсат бермейді.",
    "cli_ref_update_plan_form": "<code>update-plan --select GUID:REVISION [--select GUID:REVISION ...] [--source Configured|WindowsUpdate|MicrosoftUpdate] [--drivers] [--no-software] [--allow-restart-required] [--allow-feature-upgrade] [--json] [--execute]</code>: Алдын ала қараудың алдында жаңа іздеу жүргізіледі. Функциялық жаңартуға екі рұқсат жалаушасы да қажет және ол жалғыз таңдалуы керек. Орнатуға <code>--execute</code> және қорғаныс тексерулері растаған жарамдылық қажет. <code>update-recover</code> параметрлерді қабылдамайды және жаңартуларды ешқашан орнатпайды.",
    "cli_ref_workflow_form": "<code>workflow WORKFLOW [--recipes ID[,ID]] [--auto-repair] [--report OUTPUT.html|OUTPUT.txt] [--json]</code>: Жарамды атауларға <code>workflows</code>, рұқсат етілген рецепт ID үшін <code>recipes WORKFLOW</code> пайдаланыңыз. Нақты жұмыс ағыны <code>--auto-repair</code> қолдап, оны қабылдаған жағдайда ғана өзгертуге болады; әйтпесе тек оқу режимі. Әр жөндеуге бәрібір жарамдылық пен тексеру қажет. Common-problems/full-scan автоматты жөндеуді қабылдамайды. <code>--set KEY=VALUE</code> жоспарлары тек оқуға арналған және рецепт таңдауымен, ауқым таңдауымен не автоматты жөндеумен біріктірілмейді. Есепке әлі жоқ .html немесе .txt жолы қажет.",
    "cli_ref_workflow_scopes": "<code>workflow background-transfers [--all-users] [--json]</code>: Шектелген тасымал тексеруі, автоматты жөндеу жоқ. Installed-apps <code>--current-user</code> қабылдайды; app-packages <code>--all-users</code> және <code>--include-provisioned</code> қабылдайды. Defender <code>--skip-tpm</code>, <code>--skip-secure-boot</code> және <code>--skip-virtualization</code> қабылдайды. available-updates жұмыс ағыны <code>--source Configured|WindowsUpdate|MicrosoftUpdate</code>, <code>--drivers</code> және <code>--no-software</code> қабылдайды; оның <code>--third-party</code> параметрі қазіргі шығарылымда өшірулі.",
    "cli_ref_exit_limits": "Шығу кодын әр пәрменнің нәтижесімен бірге түсіндіріңіз: каталогты сәтті оқу, тарихи импорт, жоспар экспорты не талдау компьютердің күйі туралы қорытынды емес. symptom коды 5 бастапқы мәселенің шешілгені расталмағанын білдіреді. Нативті тексеру бұғатталған сценарийлермен де 0 қайтара алады. Толық емес деректер толық емес болып қалуы керек. <code>recover</code> пәрмендері тіркелген операцияның күйін салыстырады, оны қайталауға рұқсат бермейді.",
    "cli_ref_full_link": "Барлық пәрмендер, қабылданатын синтаксис, шығыс, шектер және орындау шарттары үшін <a href=\"../help.html#cli\">көмек бетіндегі толық пәрмен жолы анықтамасын</a> ашыңыз. Бұл бет негізгі жұмыс ағындарын таныстырады."
  },
  "nb": {
    "cli_ref_discovery": "Finne kommandoer, feilsøking og lokale bevis",
    "cli_ref_conventions": "Sett <code>killerbench-cli</code> foran hver kommando nedenfor. Bruk anførselstegn rundt stier eller tekst med mellomrom. Hakeparenteser angir valgfrie argumenter; en loddrett strek skiller alternativer. Ved <code>...</code> gjentar du hele alternativet. Alternativer gjelder bare den navngitte kommandoen. Bruk <code>capabilities</code> for den maskinlesbare navnelisten, også navn som er reservert for senere utgivelser; bruk <code>help</code>, <code>--help</code>, <code>-h</code> eller ingen argumenter for konsollhjelp.",
    "cli_ref_exceptions": "Den generelle regelen om forhåndsvisning har unntak: <code>symptom run --repair</code>, <code>workflow --auto-repair</code> og de tre strømalternativene i <code>debloat-review</code> tillater de dokumenterte endringene uten <code>--execute</code>. <code>validate-native</code> fremprovoserer feil bare i et beskyttet engangsmiljø. Eksport av pakker, lagrede planer, journaler og rapporter skriver også lokale filer. JSON er bare tilgjengelig der det er dokumentert; pakkesøk og pakkevalidering, analyse av ren tekst og flere forhåndsvisninger bruker tekst. Fremdrifts- og funksjonsmeldinger kan vises på standard feilstrøm selv om kommandoen lykkes.",
    "cli_ref_profile_backup_limits": "<code>profiles --backup-to</code> støtter ukrypterte profiloppføringer. En EFS-kryptert kilde avvises før målet for sikkerhetskopien opprettes.",
    "cli_ref_capabilities": "<code>capabilities [--json]</code>: Returnerer JSON i begge former: <code>schemaVersion</code> (1), samlingens <code>version</code> og sorterte, unike <code>commands</code> (strenger). Ingen diagnostikk eller reparasjoner. Godtar bare det valgfrie <code>--json</code>; avslutningskode 0 ved suksess, 2 for andre argumenter. Et oppført navn dokumenterer verken innebygd systemstøtte eller tilgjengelighet i utgivelsen.",
    "cli_ref_pack": "<code>pack list | pack export PACK_ID OUTPUT.json | pack validate PACK.json</code>: Lister innebygde pakker, funksjonsetiketter for oppskrifter og primitiver; eksporterer en innebygd pakke til en utdatasti som ikke finnes; eller validerer en lokal pakke mot Windows-biblioteket for primitiver. Tekstutdata; ingen oppskrifter kjøres. Eksport oppretter overordnede mapper. Koder: 0 suksess, 2 ugyldige argumenter, ukjente ID-er eller eksisterende utdata, 3 ugyldige eller uleselige pakker.",
    "cli_ref_symptom": "<code>symptom list | symptom search TEXT | symptom run SYMPTOM_ID [--repair] [--explicit] [--option NAME=VALUE]... [--answer NODE=KEY]... [--json]</code>: Lister eller søker etter støttede symptom-ID-er og kjører ett avgrenset feilsøkingstre. Som standard bare påvisning. <code>--repair</code> tillater automatiske pakkeoppskrifter med nye kontroller; <code>--explicit</code> bekrefter i tillegg oppskrifter som krever uttrykkelige alternativer, og krever <code>--repair</code>. Hver oppskrift brukes høyst én gang; standardgrenser er 40 trinn, 10 reparasjoner og 30 minutter. Ubesvarte spørsmål forblir åpne. Skriver en lokal Triage-journal og returnerer tekst eller JSON. Koder: 0 løst eller utelukket, 3 uløst eller blokkert, 4 omstart nødvendig, 5 komponentreparasjon bekreftet uten bekreftelse på at symptomet er borte, 130 avbrutt. Søk uten treff returnerer 3; ugyldig inndata 2.",
    "cli_ref_investigate": "<code>investigate FILE_PATH [--json]</code>: Bruker støttede bevisregler på en lokal tekstlogg, et lagret EVTX-arkiv eller et eksportert XML-dokument med Windows-hendelser, med forklaringer, referanser og neste trinn. Tekstimport leser høyst 1,000,000 tegn og 10,000 tolkede oppføringer. EVTX krever Windows og beholder de nyeste 200 postene; XML beholder de første 200 i filrekkefølge. Ingen av hendelsesimportene filtrerer etter dato; historiske bevis dokumenterer ikke maskinens nåværende tilstand. Analysen har en avbruddsfrist på 15 sekunder. Tekst som standard, JSON med <code>--json</code>. Koder: 0 analyse fullført, 3 delvise bevis, 1 uleselige eller ustøttede inndata, 2 ugyldige argumenter, 130 avbrudd eller tidsavbrudd. Ingen reparasjoner.",
    "cli_ref_analyze": "<code>analyze TEXT_LOG_PATH [--json]</code>: Henter observasjoner av ulike koder fra én tekstlogg uten å diagnostisere årsak eller gjøre endringer. Leser høyst 1,000,000 tegn, beholder høyst 256 koder og åtte referanser per kode; avbruddsfrist på 15 sekunder. Tekst som standard eller JSON med <code>--json</code>. Koder: 0 fullstendig analyse, 3 avkorting, 1 inndatafeil, 2 ugyldige argumenter, 130 avbrudd eller tidsavbrudd.",
    "cli_ref_duplicate_files": "<code>duplicate-files FOLDER [--min-bytes N] [--max-files N] [--report]</code>: Skrivebeskyttet SHA-256-gjennomgang av duplikater i én lokal mappe. Standard: minst én byte, 10,000 filer; minimum kan være null, filgrensen kan være 1 til 100,000. Hashing er begrenset til 100 GiB totalt. JSON som standard eller tekst med <code>--report</code>; begge kan avsløre filstier. Ingen filer velges for sletting. Koder: 0 fullstendig, 3 ufullstendig, 1 skanne-/inndatafeil, 2 feilformede alternativer, 130 avbrutt.",
    "cli_ref_large_files": "<code>large-files FOLDER [--min-bytes N] [--max-files N] [--limit N] [--report]</code>: Skrivebeskyttet størrelsesgjennomgang av én lokal mappe. Standard: minst 100 MiB, 10,000 undersøkte filer og 500 beholdte resultater. Minimum må være positivt; filgrense 1 til 100,000 og resultatgrense 1 til 10,000. JSON som standard eller tekst med <code>--report</code>; utdata inneholder filstier. Koder: 0 fullstendig, 3 ufullstendig, 1 skanne-/inndatafeil, 2 feilformede alternativer, 130 avbrutt. Ingen opprydding.",
    "cli_ref_file_limits": "Begge mappegjennomgangene hopper over reanalysepunkter og begrenser gjennomgangen: som standard 10,000 mapper, 1,024 ventende mapper, dybde 128 og 30 sekunder. Utilgjengelig innhold eller en nådd grense for gjennomgang, hashing, filer eller resultater betyr at resultatet er ufullstendig. Dette er dekningsgrenser, ikke bevis på at utelatte filer er trygge.",
    "cli_ref_debloat_recover": "<code>debloat-recover power-plan|power-timers|hibernation --folder PATH [--json]</code>: Avstemmer én type ventende strømoperasjon ved hjelp av journalmappens fullstendige sti. Velg samme mappe som inneholder den ventende posten, vanligvis <code>%LOCALAPPDATA%\\KillerBench\\Debloat</code>. Returnerer alltid JSON, med eller uten <code>--json</code>; fremdrift går til standard feilstrøm. Gjentar ikke en strømendring. Avklarte lokale poster kan arkiveres. Koder: 0 ingen ventende post eller bekreftet tilstand, 3 uavklarte bevis, 1 fil-/leverandørfeil, 2 ugyldige argumenter eller relativ/manglende mappesti, 130 avbrutt. Ingen <code>--execute</code>-opsjon.",
    "cli_ref_gated": "Utgivelsesbegrensninger og innebygd systemvalidering i engangsmiljøer",
    "cli_ref_third_party_updates": "<code>third-party-updates</code>: Reservert skrivebeskyttet søk etter programoppdateringer med Microsoft.WinGet.Client. Deaktivert i gjeldende utgivelse; returnerer 2 og tilgjengelighetsmeldingen for KillerBench 1.1 uten å søke. Når aktivert, gir den JSON; 0 fullstendig og tilgjengelig søk, 3 ufullstendig eller utilgjengelig, 1 leverandørfeil, 130 avbrudd.",
    "cli_ref_third_party_update": "<code>third-party-update ID SOURCE VERSION [--accept-agreements] [--execute]</code>: Reservert oppdatering av en nøyaktig angitt pakke; foreløpig deaktivert med kode 2. Når aktivert, forhåndsviser den som standard nylig oppdaget eksakt ID, kilde og versjon. Etter gjennomgang av valget krever kjøring begge alternativene, gjentar sikkerhetskontroller og journalfører forespørselen. JSON-utdata; kvalifisering og kjøringsresultater forblir uttrykkelige. Dupliserte eller ukjente flagg avvises. Ingen masseoppgradering eller underforstått avtaleaksept.",
    "cli_ref_third_party_recover": "<code>third-party-update-recover</code>: Reservert avstemming av en ventende eksakt versjon; foreløpig deaktivert med kode 2. Når aktivert, leser den den lokale ThirdPartyUpdates-journalen og bekrefter tilstanden uten å prøve installasjonen på nytt. JSON-utdata; 0 ingen ventende post eller bekreftet tilstand, 3 uavklarte bevis, 130 avbrudd. Godtar ingen alternativer.",
    "cli_ref_validate_native": "<code>validate-native RECIPE_ID SCENARIO_SUFFIX|all OUTPUT_DIR --disposable MACHINE_NAME</code>: Validering ved feilinjeksjon, ikke skrivebeskyttet diagnostikk eller forhåndsvisning. Krever administratortilgang, maskinens nøyaktige navn og <code>KILLERBENCH_DISPOSABLE=yes-this-machine-is-disposable</code> på en Windows-maskin som kan kastes etter testen. Bruk aldri en utviklingsmaskin eller kundemaskin. Kjører det valgte installerte scenarioet eller alle scenarioene for oppskriften, forsøker gjenoppretting og skriver poster og artefakter under OUTPUT_DIR. Tekstutdata; 3 hvis et scenario feiler, 0 hvis ingen feiler (blokkerte scenarioer kan fortsatt finnes), 2 ved avvisning fra sikkerhetskontroller eller ugyldige inndata, 130 ved avbrudd. Undersøk alle resultater og gjenopprettingsposter; kode 0 alene er ingen godkjenning av valideringen.",
    "cli_ref_forms": "Flere godtatte alternativer og arbeidsflytformer",
    "cli_ref_forms_intro": "Den kategoriserte referansen nedenfor dekker alle offentlige kommandoer. Disse utvidede formene beholder alternativer som er lette å overse i de korte oppføringene.",
    "cli_ref_bitlocker_form": "<code>bitlocker-plan [--volume C:] [--operation Inspect|BackupRecovery|Encrypt|ResumeProtection] [--encryption Aes128|Aes256|XtsAes128|XtsAes256] [--used-space-only] [--backup File|ActiveDirectory|EntraId] [--backup-file PATH] [--inspect]</code>: Bare planlegging i tekst. <code>--inspect</code> leser det valgte volumet uten å endre beskyttelsesinnstillinger. Bruk den egne beskyttede kommandoen for en faktisk operasjon.",
    "cli_ref_debloat_form": "<code>debloat-review --area AREA [--area AREA ...] [--all-profiles] [--keep-office-culture CULTURE] [--sleep-ac MINUTES --sleep-dc MINUTES --display-ac MINUTES --display-dc MINUTES] [--apply-high-performance|--apply-power-timers|--disable-hibernation] [--json]</code>: Gjennomgang som standard. Hvert uttrykkelig strømalternativ gjør en endring uten ekstra <code>--execute</code>. Velg nøyaktig ett kjøringsalternativ og bare det tilhørende området: HighPerformancePower, SleepAndDisplayTimers eller Hibernation. Alle fire tidsverdiene kreves sammen, hver fra 0 til 1440 minutter; null betyr Aldri. Eksisterende ventende strømposter avstemmes i stedet for å gjenta endringen. Tekst som standard eller JSON med <code>--json</code>; blokkerte eller ubekreftede bevis forblir tydelig angitt.",
    "cli_ref_depot_form": "<code>depot-review [--microsoft-365] [--onedrive] [--teams] [--chrome] [--acrobat-reader] [--zoom] [--7zip] [--windows-updates] [--computer-name] [--local-admin] [--admin-review] [--browser-extensions] [--cleanup] [--edge] [--privacy] [--taskbar] [--start-menu] [--notifications] [--json]</code>: Velg minst én program- eller konfigurasjonsgruppe. Bare klargjøringsgjennomgang i tekst eller JSON; ingen nedlasting av installasjonsprogram, oppretting av konto eller konfigurasjonsendring.",
    "cli_ref_audio_form": "<code>device-check audio [--knowledge PACK_PATH ...] [--direction output|input] [--role console|multimedia|communications]</code>: Valgfrie retnings- og rollefiltre gjelder bare lyd. Gjenta <code>--knowledge PATH</code> for hver av høyst 32 pakker. Skrivebeskyttet JSON; ingen av filtrene endrer standard lydendepunkt.",
    "cli_ref_privacy_form": "<code>privacy-plan [--select AREA ...] [--inspect]</code>: Tekstforhåndsvisning eller skrivebeskyttet registerinspeksjon. Alle seks action-, recover- og undo-formene for <code>privacy-setting</code> og <code>privacy-clipboard-history</code> godtar også <code>--journal-folder PATH</code>. Bruk samme mappe til kjøring og gjenoppretting. Handlinger og angring er bare forhåndsvisning uten <code>--execute</code>; gjenoppretting gjentar aldri endringen.",
    "cli_ref_update_search_form": "<code>update-search [--source Configured|WindowsUpdate|MicrosoftUpdate] [--drivers] [--no-software] [--filter TITLE] [--downloaded-only] [--classification GUID] [--product GUID]</code>: Skrivebeskyttet søk med JSON og nøyaktig samsvarende identiteter. Kildevalget tillater ikke nedlasting eller installasjon.",
    "cli_ref_update_plan_form": "<code>update-plan --select GUID:REVISION [--select GUID:REVISION ...] [--source Configured|WindowsUpdate|MicrosoftUpdate] [--drivers] [--no-software] [--allow-restart-required] [--allow-feature-upgrade] [--json] [--execute]</code>: Nytt søk utføres før forhåndsvisning. Funksjonsoppgraderinger krever begge tillatelsesflaggene og må velges alene. Installasjon krever <code>--execute</code> og kvalifisering gjennom sikkerhetskontrollene. <code>update-recover</code> godtar ingen alternativer og installerer aldri oppdateringer.",
    "cli_ref_workflow_form": "<code>workflow WORKFLOW [--recipes ID[,ID]] [--auto-repair] [--report OUTPUT.html|OUTPUT.txt] [--json]</code>: Bruk <code>workflows</code> for gyldige navn og <code>recipes WORKFLOW</code> for tillatte oppskrifts-ID-er. Skrivebeskyttet med mindre den målrettede arbeidsflyten støtter og mottar <code>--auto-repair</code>; hver reparasjon krever fortsatt kvalifisering og bekreftelse. Common-problems/full-scan avviser automatisk reparasjon. <code>--set KEY=VALUE</code>-planer forblir skrivebeskyttet og kan ikke kombineres med oppskriftsvalg, omfangsvalg eller automatisk reparasjon. En rapport krever en .html- eller .txt-sti som ikke finnes fra før.",
    "cli_ref_workflow_scopes": "<code>workflow background-transfers [--all-users] [--json]</code>: Avgrenset overføringsinspeksjon uten automatisk reparasjon. Installed-apps godtar <code>--current-user</code>; app-packages godtar <code>--all-users</code> og <code>--include-provisioned</code>. Defender godtar <code>--skip-tpm</code>, <code>--skip-secure-boot</code> og <code>--skip-virtualization</code>. Arbeidsflyten available-updates godtar <code>--source Configured|WindowsUpdate|MicrosoftUpdate</code>, <code>--drivers</code> og <code>--no-software</code>; alternativet <code>--third-party</code> er deaktivert i gjeldende utgivelse.",
    "cli_ref_exit_limits": "Tolk avslutningskoder sammen med hvert kommandoresultat: vellykket kataloglesing, historisk import, planeksport eller analyse er ingen tilstandsvurdering av maskinen. Kode 5 fra symptom betyr at det opprinnelige problemets løsning ikke er bekreftet. Innebygd systemvalidering kan returnere 0 med blokkerte scenarioer. Ufullstendige bevis må forbli ufullstendige. <code>recover</code>-kommandoer avstemmer den registrerte operasjonen og gir ikke tillatelse til å prøve den på nytt.",
    "cli_ref_full_link": "Alle kommandoer, godtatt syntaks, utdata, grenser og kjøringsvilkår finnes i <a href=\"../help.html#cli\">den fullstendige kommandolinjereferansen på hjelpesiden</a>. Denne siden presenterer de viktigste arbeidsflytene."
  }
};
  Object.keys(translations).forEach(function (locale) {
    Object.assign(I18N[locale], translations[locale]);
  });
}());
